/*
 * figlet.c - FIGlet implementation
 * Reimplemented from behavioral observation of FIGlet 2.2.5
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <sys/ioctl.h>

#define FIGLET_VERSION "2.2.5"
#define FIGLET_DATE "31 May 2012"
#define FIGLET_VERSION_INT 20205
#define DEFAULT_FONT "standard"
#define DEFAULT_WIDTH 80

/* Smush rules */
#define SM_EQUAL      1
#define SM_UNDERSCORE 2
#define SM_HIERARCHY  4
#define SM_PAIR       8
#define SM_BIGX       16
#define SM_HARDBLANK  32
#define SM_KERN       64
#define SM_SMUSH      128

/* Layout modes */
#define SMUSH_MODE_UNIVERSAL  0   /* no rules, just overlap */
#define SMUSH_MODE_KERN       1
#define SMUSH_MODE_SMUSH      2
#define SMUSH_MODE_FULL       3   /* full width */
#define SMUSH_MODE_OVERLAP    4   /* overlap */

/* Max chars in font */
#define MAX_CHARS 65536
#define MAX_HEIGHT 100
#define MAX_LINE_LEN 2048

typedef struct {
    char **lines;    /* height rows, each is the character's row */
    int width;       /* width of the character */
} FigChar;

typedef struct {
    char hardblank;
    int height;
    int baseline;
    int maxLength;
    int oldLayout;
    int printDir;    /* 0=L-R, 1=R-L */
    int fullLayout;
    int codeTagCount;
    int isTlf;       /* 1 if TLF format */
    FigChar *chars[MAX_CHARS];
} FigFont;

/* Translation table entry */
typedef struct TransEntry {
    long src;
    long dst;
    struct TransEntry *next;
} TransEntry;

/* Translation table range */
typedef struct TransRange {
    long srcStart, srcEnd;
    long dstStart;
    struct TransRange *next;
} TransRange;

/* Input modes */
#define INPUT_NORMAL 0
#define INPUT_UTF8   1
#define INPUT_HZ     2

typedef struct {
    TransRange *ranges;
    TransEntry *entries;
    int inputMode;    /* ISO2022 state changes */
    /* g tables: g[0..3] -> designator info */
    int gSet[4];      /* character set index */
    int gSize[4];     /* 94 or 96 */
    int gGL;          /* which g is in GL (0 or 1 or 2 or 3) */
    int gGR;          /* which g is in GR */
} CtrlFile;

/* Global state */
static FigFont *theFont = NULL;
static CtrlFile *ctrlFiles[64];
static int numCtrlFiles = 0;

static char *fontDir = NULL;
static char *fontName = NULL;
static int outputWidth = DEFAULT_WIDTH;
static int smushMode = -1;        /* -1 = use font default */
static int smushRules = 0;
static int justify = -1;          /* -1 = auto, 0=left, 1=center, 2=right */
static int printDir = -1;         /* -1 = use font default */
static int paragraphMode = 0;
static int infoCode = -1;
static int germanMode = 0;

/* Utility: read a line from file, return length or -1 on EOF */
static int readLine(FILE *f, char *buf, int maxlen) {
    int c, i = 0;
    while ((c = fgetc(f)) != EOF) {
        if (c == '\n') break;
        if (c == '\r') {
            c = fgetc(f);
            if (c != '\n' && c != EOF) ungetc(c, f);
            break;
        }
        if (i < maxlen - 1) buf[i++] = c;
    }
    if (c == EOF && i == 0) return -1;
    buf[i] = 0;
    return i;
}

/* Free a figchar */
static void freeFigChar(FigChar *fc) {
    if (!fc) return;
    if (fc->lines) {
        for (int i = 0; i < 100; i++) {
            if (fc->lines[i]) free(fc->lines[i]);
            else break;
        }
        free(fc->lines);
    }
    free(fc);
}

/* Free the font */
static void freeFont(FigFont *f) {
    if (!f) return;
    for (int i = 0; i < MAX_CHARS; i++) {
        if (f->chars[i]) freeFigChar(f->chars[i]);
    }
    free(f);
}

/* Try to open a file from font dir or current dir */
static FILE *openFontFile(const char *dir, const char *name, const char *ext) {
    char path[1024];
    FILE *f;

    if (dir && dir[0]) {
        snprintf(path, sizeof(path), "%s/%s.%s", dir, name, ext);
        f = fopen(path, "r");
        if (f) return f;
    }

    /* Try current dir */
    snprintf(path, sizeof(path), "%s.%s", name, ext);
    f = fopen(path, "r");
    if (f) return f;

    /* Try the name as-is if it has an extension already */
    f = fopen(name, "r");
    return f;
}

/* Parse a unicode escape like \0x1234 or \-252 or just a char */
/* Returns length consumed from s, sets *val to the unicode value */
static int parseEscape(const char *s, long *val) {
    if (s[0] == '\\') {
        if (s[1] == '0' && (s[2] == 'x' || s[2] == 'X')) {
            /* \0xHHHH */
            char *end;
            *val = strtol(s + 3, &end, 16);
            return (int)(end - s);
        } else if (s[1] == '-' || isdigit((unsigned char)s[1])) {
            /* \NNN (decimal, possibly negative) */
            char *end;
            *val = strtol(s + 1, &end, 10);
            return (int)(end - s);
        } else {
            *val = (unsigned char)s[1];
            return 2;
        }
    } else {
        /* Regular character - but could be multi-byte UTF-8 */
        unsigned char c = (unsigned char)s[0];
        if (c < 0x80) {
            *val = c;
            return 1;
        } else if (c < 0xE0) {
            *val = ((c & 0x1F) << 6) | ((unsigned char)s[1] & 0x3F);
            return 2;
        } else if (c < 0xF0) {
            *val = ((c & 0x0F) << 12) | (((unsigned char)s[1] & 0x3F) << 6) | ((unsigned char)s[2] & 0x3F);
            return 3;
        } else {
            *val = ((c & 0x07) << 18) | (((unsigned char)s[1] & 0x3F) << 12) | 
                   (((unsigned char)s[2] & 0x3F) << 6) | ((unsigned char)s[3] & 0x3F);
            return 4;
        }
    }
}

/* Apply a translation to a codepoint; returns translated value or -1 if no translation */
static long applyCtrlFiles(long cp) {
    for (int i = 0; i < numCtrlFiles; i++) {
        CtrlFile *cf = ctrlFiles[i];
        /* Check entries */
        for (TransEntry *e = cf->entries; e; e = e->next) {
            if (e->src == cp) return e->dst;
        }
        /* Check ranges */
        for (TransRange *r = cf->ranges; r; r = r->next) {
            if (cp >= r->srcStart && cp <= r->srcEnd) {
                return r->dstStart + (cp - r->srcStart);
            }
        }
    }
    return cp;
}

/* Load a control file */
static CtrlFile *loadCtrlFile(const char *filename) {
    FILE *f = fopen(filename, "r");
    if (!f) {
        /* Try with .flc extension */
        char path[1024];
        snprintf(path, sizeof(path), "%s.flc", filename);
        f = fopen(path, "r");
        if (!f) {
            if (fontDir && fontDir[0]) {
                snprintf(path, sizeof(path), "%s/%s", fontDir, filename);
                f = fopen(path, "r");
                if (!f) {
                    snprintf(path, sizeof(path), "%s/%s.flc", fontDir, filename);
                    f = fopen(path, "r");
                }
            }
        }
    }
    if (!f) return NULL;

    CtrlFile *cf = calloc(1, sizeof(CtrlFile));
    cf->gGL = 0;
    cf->gGR = 1;

    char line[MAX_LINE_LEN];
    int firstLine = 1;

    while (readLine(f, line, MAX_LINE_LEN) >= 0) {
        /* Check for magic header on first line */
        if (firstLine) {
            firstLine = 0;
            if (strncmp(line, "flc2", 4) == 0) continue; /* skip header */
        }

        if (line[0] == '#') continue; /* comment */
        if (line[0] == 'f') {
            /* freeze - treat as start of new file context */
            continue;
        }
        if (line[0] == 'u') {
            cf->inputMode = INPUT_UTF8;
            continue;
        }
        if (line[0] == 'h') {
            cf->inputMode = INPUT_HZ;
            continue;
        }
        if (line[0] == 'g') {
            /* ISO 2022 g command - skip for now */
            continue;
        }

        /* Check for tab-separated format (like 8859-2.flc) */
        /* Format: 0xXX\t0xXXXX\t# comment */
        if (line[0] == '0' && line[1] == 'x') {
            char *tab1 = strchr(line, '\t');
            if (tab1) {
                long src = strtol(line, NULL, 16);
                long dst = strtol(tab1 + 1, NULL, 16);
                TransEntry *e = malloc(sizeof(TransEntry));
                e->src = src;
                e->dst = dst;
                e->next = cf->entries;
                cf->entries = e;
            }
            continue;
        }

        if (line[0] == 't') {
            /* translate command: t src dst */
            /* src and dst can be ranges: a-z or single chars */
            char *p = line + 1;
            while (*p == ' ' || *p == '\t') p++;

            /* Parse source */
            long srcStart, srcEnd, dstStart;
            int len = parseEscape(p, &srcStart);
            p += len;
            srcEnd = srcStart;

            if (*p == '-') {
                p++;
                long tmp;
                len = parseEscape(p, &tmp);
                p += len;
                srcEnd = tmp;
            }

            while (*p == ' ' || *p == '\t') p++;

            if (*p == 0) continue; /* no destination */

            len = parseEscape(p, &dstStart);
            p += len;

            long dstEnd = dstStart;
            if (*p == '-') {
                p++;
                long tmp;
                len = parseEscape(p, &tmp);
                p += len;
                dstEnd = tmp;
            }
            (void)dstEnd;

            if (srcStart == srcEnd) {
                /* Single entry */
                TransEntry *e = malloc(sizeof(TransEntry));
                e->src = srcStart;
                e->dst = dstStart;
                e->next = cf->entries;
                cf->entries = e;
            } else {
                /* Range */
                TransRange *r = malloc(sizeof(TransRange));
                r->srcStart = srcStart;
                r->srcEnd = srcEnd;
                r->dstStart = dstStart;
                r->next = cf->ranges;
                cf->ranges = r;
            }
            continue;
        }

        /* Could be tab-separated without 0x prefix - try to parse */
        /* This handles lines that start with just numbers */
    }

    fclose(f);
    return cf;
}

/* Parse a single FIG char from file; returns 1 on success */
static FigChar *parseFigChar(FILE *f, int height, char hardblank, int isTlf) {
    FigChar *fc = malloc(sizeof(FigChar));
    fc->lines = malloc((height + 1) * sizeof(char *));
    fc->width = 0;
    memset(fc->lines, 0, (height + 1) * sizeof(char *));

    char line[MAX_LINE_LEN];
    for (int row = 0; row < height; row++) {
        if (readLine(f, line, MAX_LINE_LEN) < 0) {
            freeFigChar(fc);
            return NULL;
        }

        /* Find end marker: @ or ! */
        char endMark = isTlf ? '!' : '@';
        int len = strlen(line);

        /* Remove trailing end marks */
        while (len > 0 && line[len-1] == endMark) {
            line[--len] = 0;
        }

        /* Replace hardblank with real space and track width */
        /* The width is the byte-length of this row */
        /* But we need Unicode-aware width for display */
        fc->lines[row] = strdup(line);
        if (len > fc->width) fc->width = len;
    }
    fc->lines[height] = NULL;

    return fc;
}

/* Load a FIG font from file */
static FigFont *loadFont(const char *dir, const char *name) {
    FILE *f = NULL;
    char path[1024];

    /* Check if name already has extension */
    int hasExt = 0;
    const char *dot = strrchr(name, '.');
    if (dot && (strcmp(dot, ".flf") == 0 || strcmp(dot, ".tlf") == 0)) {
        hasExt = 1;
    }

    /* Try full path if it looks absolute */
    if (name[0] == '/') {
        f = fopen(name, "r");
        if (!f && !hasExt) {
            snprintf(path, sizeof(path), "%s.flf", name);
            f = fopen(path, "r");
            if (!f) {
                snprintf(path, sizeof(path), "%s.tlf", name);
                f = fopen(path, "r");
            }
        }
    }

    if (!f && dir && dir[0]) {
        if (hasExt) {
            snprintf(path, sizeof(path), "%s/%s", dir, name);
        } else {
            snprintf(path, sizeof(path), "%s/%s.flf", dir, name);
        }
        f = fopen(path, "r");
        if (!f && !hasExt) {
            snprintf(path, sizeof(path), "%s/%s.tlf", dir, name);
            f = fopen(path, "r");
        }
    }

    if (!f) {
        /* Try current dir */
        if (hasExt) {
            f = fopen(name, "r");
        } else {
            snprintf(path, sizeof(path), "%s.flf", name);
            f = fopen(path, "r");
            if (!f) {
                snprintf(path, sizeof(path), "%s.tlf", name);
                f = fopen(path, "r");
            }
        }
    }

    if (!f) return NULL;

    char header[MAX_LINE_LEN];
    if (readLine(f, header, MAX_LINE_LEN) < 0) {
        fclose(f);
        return NULL;
    }

    FigFont *font = calloc(1, sizeof(FigFont));
    int isTlf = 0;

    /* Check magic */
    if (strncmp(header, "flf2", 4) == 0) {
        isTlf = 0;
    } else if (strncmp(header, "tlf2", 4) == 0) {
        isTlf = 1;
    } else {
        fprintf(stderr, "Not a FIGlet 2 font file\n");
        free(font);
        fclose(f);
        return NULL;
    }
    font->isTlf = isTlf;

    /* Parse header: magic<hardblank> height baseline maxLength oldLayout commentLines [dir] [fullLayout] [codeTagCount] */
    char *p = header + 4; /* skip flf2 or tlf2 */
    /* Skip 'a' if present */
    if (*p == 'a') p++;

    if (isTlf) {
        /* TLF: no hardblank character, space separator */
        font->hardblank = 0; /* no hardblank for TLF */
        if (*p == ' ') p++; /* skip space */
    } else {
        /* FLF: next char is hardblank */
        font->hardblank = *p++;
        if (*p == ' ') p++; /* skip space */
    }

    font->height = atoi(p);
    while (*p && !isspace((unsigned char)*p)) p++;
    while (*p && isspace((unsigned char)*p)) p++;

    font->baseline = atoi(p);
    while (*p && !isspace((unsigned char)*p)) p++;
    while (*p && isspace((unsigned char)*p)) p++;

    font->maxLength = atoi(p);
    while (*p && !isspace((unsigned char)*p)) p++;
    while (*p && isspace((unsigned char)*p)) p++;

    font->oldLayout = atoi(p);
    while (*p && !isspace((unsigned char)*p)) p++;
    while (*p && isspace((unsigned char)*p)) p++;

    int commentLines = atoi(p);
    while (*p && !isspace((unsigned char)*p)) p++;
    while (*p && isspace((unsigned char)*p)) p++;

    font->printDir = 0;
    if (*p) {
        font->printDir = atoi(p);
        while (*p && !isspace((unsigned char)*p)) p++;
        while (*p && isspace((unsigned char)*p)) p++;
    }

    font->fullLayout = 0;
    if (*p) {
        font->fullLayout = atoi(p);
        while (*p && !isspace((unsigned char)*p)) p++;
        while (*p && isspace((unsigned char)*p)) p++;
    }

    font->codeTagCount = 0;
    if (*p) {
        font->codeTagCount = atoi(p);
    }

    /* Skip comment lines */
    char line[MAX_LINE_LEN];
    for (int i = 0; i < commentLines; i++) {
        if (readLine(f, line, MAX_LINE_LEN) < 0) break;
    }

    /* Read standard 95 chars (ASCII 32-126) */
    for (int ch = 32; ch <= 126; ch++) {
        FigChar *fc = parseFigChar(f, font->height, font->hardblank, isTlf);
        if (!fc) break;
        font->chars[ch] = fc;
    }

    /* Read Deutsch chars 196 (Ä), 214 (Ö), 220 (Ü), 228 (ä), 246 (ö), 252 (ü), 223 (ß) */
    /* These are the 7 extra chars in the "standard" FLF set after ASCII 32-126 */
    static const int deutschChars[] = {196, 214, 220, 228, 246, 252, 223};
    for (int i = 0; i < 7; i++) {
        FigChar *fc = parseFigChar(f, font->height, font->hardblank, isTlf);
        if (!fc) break;
        font->chars[deutschChars[i]] = fc;
    }

    /* Read code-tagged chars */
    for (int i = 0; ; i++) {
        /* Try to read tag line */
        long pos = ftell(f);
        if (readLine(f, line, MAX_LINE_LEN) < 0) break;

        /* Skip empty lines */
        if (line[0] == 0) {
            /* Skip blank lines between chars */
            continue;
        }

        /* Parse the code tag - could be decimal or hex */
        long code = 0;
        char *end = NULL;

        /* Skip leading whitespace */
        char *lp = line;
        while (*lp == ' ' || *lp == '\t') lp++;

        if (*lp == 0) continue; /* blank line */

        if (*lp == '-' || isdigit((unsigned char)*lp)) {
            code = strtol(lp, &end, 0);
        } else if (*lp == '0' && (*(lp+1) == 'x' || *(lp+1) == 'X')) {
            code = strtol(lp, &end, 16);
        } else {
            /* Not a code tag - maybe we're done? */
            fseek(f, pos, SEEK_SET);
            break;
        }

        if (end == lp) {
            fseek(f, pos, SEEK_SET);
            break;
        }

        if (code <= 0 || code >= MAX_CHARS) {
            /* Invalid code, skip this character definition */
            for (int row = 0; row < font->height; row++) {
                if (readLine(f, line, MAX_LINE_LEN) < 0) goto done_reading;
            }
            continue;
        }

        FigChar *fc = parseFigChar(f, font->height, font->hardblank, isTlf);
        if (!fc) break;

        if (font->chars[code]) freeFigChar(font->chars[code]);
        font->chars[code] = fc;
    }
    done_reading:

    fclose(f);
    return font;
}

/* Calculate smush rules based on mode and font */
static int calcSmushMode(FigFont *font) {
    /* Return the effective smush rules */
    if (smushMode == -2) {
        /* -s: use font default */
        return font->fullLayout;
    }
    if (smushMode == -1) {
        /* Full width */
        return -1; /* special value */
    }
    if (smushMode == 0) {
        /* -k: kern only */
        return SM_KERN;
    }
    /* explicit -m value */
    return smushMode | SM_SMUSH;
}

/* Get the smush amount between two figchars */
/* Returns how many columns to overlap */
static int smushAmount(FigFont *font, FigChar *left, FigChar *right, int layout) {
    if (layout == -1) return 1; /* full width: 1 space between */

    int isSmush = (layout & SM_SMUSH) != 0;
    int isKern = (layout & SM_KERN) != 0;

    if (!isSmush && !isKern) {
        /* Universal smushing or overlap */
        isSmush = 1; /* will use overlap as fallback */
    }

    int maxSmush = left->width + right->width;
    int result = 0;

    for (int col = 0; col < maxSmush; col++) {
        /* For each column, check if we can move right one more */
        /* col = how many columns we try to overlap */
        /* Check all rows */
        int canMove = 1;

        for (int row = 0; row < font->height; row++) {
            const char *leftLine = left->lines[row] ? left->lines[row] : "";
            const char *rightLine = right->lines[row] ? right->lines[row] : "";
            int lLen = strlen(leftLine);
            int rLen = strlen(rightLine);

            /* Left char's rightmost visible col when overlapping by col+1 */
            int lPos = lLen - (col + 1);
            char lc = (lPos >= 0 && lPos < lLen) ? leftLine[lPos] : ' ';
            /* Replace hardblank */
            if (font->hardblank && lc == font->hardblank) lc = ' ';

            /* Right char's leftmost col */
            char rc = (col + 1 <= (int)(rLen) && (int)rLen > 0) ? rightLine[0] : ' ';
            if (col < (int)rLen) rc = rightLine[0]; /* first column of right */
            /* Actually we need the column at position 0 for right char */
            rc = (rLen > 0) ? rightLine[0] : ' ';
            if (font->hardblank && rc == font->hardblank) rc = ' ';

            /* Check if overlap is possible */
            if (lc != ' ' && rc != ' ') {
                canMove = 0;
                break;
            }
        }

        if (!canMove) break;
        result = col + 1;
    }

    return result;
}

