                    if (space + 1 < amnt) amnt = space + 1; /* don't increase */
                    /* Actually this checks if THIS row allows one more overlap */
                }
            }
        }

        (void)rowAmnt;
    }

    if (amnt < 0) amnt = 0;
    return amnt;
}

