/* Parse a single FIG char from file; returns 1 on success */
static FigChar *parseFigChar(FILE *f, int height, char hardblank, int isTlf) {
    FigChar *fc = malloc(sizeof(FigChar));
    fc->lines = malloc((height + 1) * sizeof(char *));
    fc->width = 0;
    memset(fc->lines, 0, (height + 1) * sizeof(char *));

    char line[MAX_LINE_LEN];
    for (int row = 0; row < height; row++) {
        if (readLine(f, line, MAX_LINE_LEN) < 0) {
            freeFigChar(fc);
            return NULL;
        }

        /* Find end marker: @ or ! */
        char endMark = isTlf ? '!' : '@';
        int len = strlen(line);

        /* Remove trailing end marks */
        while (len > 0 && line[len-1] == endMark) {
            line[--len] = 0;
        }

        /* Replace hardblank with real space and track width */
        /* The width is the byte-length of this row */
        /* But we need Unicode-aware width for display */
        fc->lines[row] = strdup(line);
        if (len > fc->width) fc->width = len;
    }
    fc->lines[height] = NULL;

    return fc;
}

