/* Calculate smush rules based on mode and font */
static int calcSmushMode(FigFont *font) {
    /* Return the effective smush rules */
    if (smushMode == -2) {
        /* -s: use font default */
        return font->fullLayout;
    }
    if (smushMode == -1) {
        /* Full width */
        return -1; /* special value */
    }
    if (smushMode == 0) {
        /* -k: kern only */
        return SM_KERN;
    }
    /* explicit -m value */
    return smushMode | SM_SMUSH;
}

/* Get the smush amount between two figchars */
/* Returns how many columns to overlap */
static int smushAmount(FigFont *font, FigChar *left, FigChar *right, int layout) {
    if (layout == -1) return 1; /* full width: 1 space between */

    int isSmush = (layout & SM_SMUSH) != 0;
    int isKern = (layout & SM_KERN) != 0;

    if (!isSmush && !isKern) {
        /* Universal smushing or overlap */
        isSmush = 1; /* will use overlap as fallback */
    }

    int maxSmush = left->width + right->width;
    int result = 0;

    for (int col = 0; col < maxSmush; col++) {
        /* For each column, check if we can move right one more */
        /* col = how many columns we try to overlap */
        /* Check all rows */
        int canMove = 1;

        for (int row = 0; row < font->height; row++) {
            const char *leftLine = left->lines[row] ? left->lines[row] : "";
            const char *rightLine = right->lines[row] ? right->lines[row] : "";
            int lLen = strlen(leftLine);
            int rLen = strlen(rightLine);

            /* Left char's rightmost visible col when overlapping by col+1 */
            int lPos = lLen - (col + 1);
            char lc = (lPos >= 0 && lPos < lLen) ? leftLine[lPos] : ' ';
            /* Replace hardblank */
            if (font->hardblank && lc == font->hardblank) lc = ' ';

            /* Right char's leftmost col */
            char rc = (col + 1 <= (int)(rLen) && (int)rLen > 0) ? rightLine[0] : ' ';
            if (col < (int)rLen) rc = rightLine[0]; /* first column of right */
            /* Actually we need the column at position 0 for right char */
            rc = (rLen > 0) ? rightLine[0] : ' ';
            if (font->hardblank && rc == font->hardblank) rc = ' ';

            /* Check if overlap is possible */
            if (lc != ' ' && rc != ' ') {
                canMove = 0;
                break;
            }
        }

        if (!canMove) break;
        result = col + 1;
    }

    return result;
}

