}

/* Get the smushed character for two adjacent sub-chars */
/* Returns 0 if can't smush, or the smushed char */
static char smushChars(char left, char right, char hardblank, int smushRules) {
    if (left == ' ') return right;
    if (right == ' ') return left;

    /* If either is hardblank */
    if (hardblank && left == hardblank && right == hardblank) {
        if (smushRules & SM_HARDBLANK) return hardblank;
        return 0;
    }
    if (hardblank && (left == hardblank || right == hardblank)) {
        if (smushRules & SM_HARDBLANK) {
            return hardblank;
        }
        return 0;
    }

    if (!(smushRules & SM_SMUSH)) {
        /* Universal smush: just return the right char */
        return right;
    }

    /* SMUSH_EQUAL: same char */
    if (smushRules & SM_EQUAL) {
        if (left == right && !(hardblank && left == hardblank)) return left;
    }

    /* SMUSH_UNDERSCORE: _ smushed with hierarchy chars */
    if (smushRules & SM_UNDERSCORE) {
        static const char *us = "|/\\[]{}()<>";
        if (left == '_' && strchr(us, right)) return right;
        if (right == '_' && strchr(us, left)) return left;
    }

    /* SMUSH_HIERARCHY: hierarchy of chars |> /\ []{}() <> */
    if (smushRules & SM_HIERARCHY) {
        static const char *classes[] = {"|", "/\\", "[]", "{}", "()", "<>", NULL};
        int leftClass = -1, rightClass = -1;
        for (int i = 0; classes[i]; i++) {
            if (strchr(classes[i], left)) leftClass = i;
            if (strchr(classes[i], right)) rightClass = i;
        }
        if (leftClass >= 0 && rightClass >= 0 && leftClass != rightClass) {
            return (leftClass > rightClass) ? left : right;
        }
    }

    /* SMUSH_PAIR: pair of brackets */
    if (smushRules & SM_PAIR) {
        if ((left == '[' && right == ']') || (left == ']' && right == '[')) return '|';
        if ((left == '{' && right == '}') || (left == '}' && right == '{')) return '|';
        if ((left == '(' && right == ')') || (left == ')' && right == '(')) return '|';
    }

    /* SMUSH_BIGX: / and \ become X */
    if (smushRules & SM_BIGX) {
        if (left == '/' && right == '\\') return '|';
        if (left == '\\' && right == '/') return 'Y';
        if (left == '>' && right == '<') return 'X';
    }

    return 0; /* can't smush */
}

