        const char *cLine = fc->lines[row] ? fc->lines[row] : "";
        int bLen = strlen(bLine);
        int cLen = strlen(cLine);

        /* Find how far right we can push */
        int rowAmnt = 0;
        int limit = bLen + cLen;

        for (int i = 0; i <= limit; i++) {
            /* Try overlapping by i+1 */
            /* Left char at position bLen-(i+1) */
            int lPos = bLen - (i + 1);
            char lc = (lPos >= 0) ? bLine[lPos] : ' ';
            if (font->hardblank && lc == font->hardblank) lc = ' ';

            /* Right char at position 0+i... wait, for right char we look at position i from left */
            /* Actually: when overlapping by n, left's last n chars overlap with right's first n chars */
            /* For position offset i (0-based), left's col is bLen-1-i from end = bLen-(n) + (n-1-i) */
            /* This is getting complex - let me think differently */
            /* When overlap=n: left column = bLen-n+j, right column = j, for j=0..n-1 */
            /* We want max n such that for all rows and all j, can smush left[bLen-n+j] with right[j] */
            break;
        }

        /* Simple approach: find rightmost non-space in left, leftmost non-space in right */
        int lEdge = bLen - 1;
        while (lEdge >= 0 && (bLine[lEdge] == ' ' || (font->hardblank && bLine[lEdge] == font->hardblank))) lEdge--;

        int rEdge = 0;
        while (rEdge < cLen && (cLine[rEdge] == ' ' || (font->hardblank && cLine[rEdge] == font->hardblank))) rEdge++;

        /* Space between right edge of left and left edge of right (when at full width) */
        int space = bLen - lEdge - 1 + rEdge;

        if (space < amnt) amnt = space;

        /* Check if smushing could give us one more */
        if (layout & SM_SMUSH) {
            /* Check if the first collision can be smushed */
            if (lEdge >= 0 && rEdge < cLen) {
                char lc = bLine[lEdge];
