/* Utility: read a line from file, return length or -1 on EOF */
static int readLine(FILE *f, char *buf, int maxlen) {
    int c, i = 0;
    while ((c = fgetc(f)) != EOF) {
        if (c == '\n') break;
        if (c == '\r') {
            c = fgetc(f);
            if (c != '\n' && c != EOF) ungetc(c, f);
            break;
        }
        if (i < maxlen - 1) buf[i++] = c;
    }
    if (c == EOF && i == 0) return -1;
    buf[i] = 0;
    return i;
}

/* Free a figchar */
static void freeFigChar(FigChar *fc) {
