            /* Parse source */
            long srcStart, srcEnd, dstStart;
            int len = parseEscape(p, &srcStart);
            p += len;
            srcEnd = srcStart;

            if (*p == '-') {
                p++;
                long tmp;
                len = parseEscape(p, &tmp);
                p += len;
                srcEnd = tmp;
            }

            while (*p == ' ' || *p == '\t') p++;

            if (*p == 0) continue; /* no destination */

            len = parseEscape(p, &dstStart);
