        return NULL;
    }
    font->isTlf = isTlf;

    /* Parse header: magic<hardblank> height baseline maxLength oldLayout commentLines [dir] [fullLayout] [codeTagCount] */
    char *p = header + 4; /* skip flf2 or tlf2 */
    /* Skip 'a' if present */
    if (*p == 'a') p++;

    if (isTlf) {
        /* TLF: no hardblank character, space separator */
        font->hardblank = 0; /* no hardblank for TLF */
        if (*p == ' ') p++; /* skip space */
    } else {
        /* FLF: next char is hardblank */
        font->hardblank = *p++;
        if (*p == ' ') p++; /* skip space */
    }

    font->height = atoi(p);
    while (*p && !isspace((unsigned char)*p)) p++;
    while (*p && isspace((unsigned char)*p)) p++;

    font->baseline = atoi(p);
    while (*p && !isspace((unsigned char)*p)) p++;
    while (*p && isspace((unsigned char)*p)) p++;

    font->maxLength = atoi(p);
    while (*p && !isspace((unsigned char)*p)) p++;
    while (*p && isspace((unsigned char)*p)) p++;

    font->oldLayout = atoi(p);
    while (*p && !isspace((unsigned char)*p)) p++;
    while (*p && isspace((unsigned char)*p)) p++;

    int commentLines = atoi(p);
    while (*p && !isspace((unsigned char)*p)) p++;
    while (*p && isspace((unsigned char)*p)) p++;

    font->printDir = 0;
    if (*p) {
        font->printDir = atoi(p);
        while (*p && !isspace((unsigned char)*p)) p++;
        while (*p && isspace((unsigned char)*p)) p++;
    }

    font->fullLayout = 0;
    if (*p) {
        font->fullLayout = atoi(p);
        while (*p && !isspace((unsigned char)*p)) p++;
        while (*p && isspace((unsigned char)*p)) p++;
    }

    font->codeTagCount = 0;
    if (*p) {
        font->codeTagCount = atoi(p);
    }

    /* Skip comment lines */
    char line[MAX_LINE_LEN];
    for (int i = 0; i < commentLines; i++) {
        if (readLine(f, line, MAX_LINE_LEN) < 0) break;
    }

    /* Read standard 95 chars (ASCII 32-126) */
    for (int ch = 32; ch <= 126; ch++) {
        FigChar *fc = parseFigChar(f, font->height, font->hardblank, isTlf);
        if (!fc) break;
        font->chars[ch] = fc;
    }

    /* Read Deutsch chars 196 (Ä), 214 (Ö), 220 (Ü), 228 (ä), 246 (ö), 252 (ü), 223 (ß) */
    /* These are the 7 extra chars in the "standard" FLF set after ASCII 32-126 */
    static const int deutschChars[] = {196, 214, 220, 228, 246, 252, 223};
    for (int i = 0; i < 7; i++) {
        FigChar *fc = parseFigChar(f, font->height, font->hardblank, isTlf);
        if (!fc) break;
        font->chars[deutschChars[i]] = fc;
    }

    /* Read code-tagged chars */
    for (int i = 0; ; i++) {
        /* Try to read tag line */
        long pos = ftell(f);
        if (readLine(f, line, MAX_LINE_LEN) < 0) break;

        /* Skip empty lines */
        if (line[0] == 0) {
            /* Skip blank lines between chars */
            continue;
        }

        /* Parse the code tag - could be decimal or hex */
        long code = 0;
        char *end = NULL;

        /* Skip leading whitespace */
        char *lp = line;
        while (*lp == ' ' || *lp == '\t') lp++;

        if (*lp == 0) continue; /* blank line */

        if (*lp == '-' || isdigit((unsigned char)*lp)) {
            code = strtol(lp, &end, 0);
        } else if (*lp == '0' && (*(lp+1) == 'x' || *(lp+1) == 'X')) {
            code = strtol(lp, &end, 16);
        } else {
            /* Not a code tag - maybe we're done? */
            fseek(f, pos, SEEK_SET);
            break;
        }

        if (end == lp) {
            fseek(f, pos, SEEK_SET);
            break;
        }

        if (code <= 0 || code >= MAX_CHARS) {
            /* Invalid code, skip this character definition */
            for (int row = 0; row < font->height; row++) {
                if (readLine(f, line, MAX_LINE_LEN) < 0) goto done_reading;
            }
            continue;
        }

        FigChar *fc = parseFigChar(f, font->height, font->hardblank, isTlf);
        if (!fc) break;

        if (font->chars[code]) freeFigChar(font->chars[code]);
        font->chars[code] = fc;
    }
    done_reading:

    fclose(f);
    return font;
}

/* Calculate smush rules based on mode and font */
static int calcSmushMode(FigFont *font) {
    /* Return the effective smush rules */
    if (smushMode == -2) {
        /* -s: use font default */
        return font->fullLayout;
    }
    if (smushMode == -1) {
        /* Full width */
        return -1; /* special value */
    }
    if (smushMode == 0) {
        /* -k: kern only */
        return SM_KERN;
    }
    /* explicit -m value */
    return smushMode | SM_SMUSH;
