/* Get the smushed character for two adjacent sub-chars */
/* Returns 0 if can't smush, or the smushed char */
static char smushChars(char left, char right, char hardblank, int smushRules) {
    if (left == ' ') return right;
    if (right == ' ') return left;

    /* If either is hardblank */
    if (hardblank && left == hardblank && right == hardblank) {
        if (smushRules & SM_HARDBLANK) return hardblank;
        return 0;
    }
    if (hardblank && (left == hardblank || right == hardblank)) {
        if (smushRules & SM_HARDBLANK) {
            return hardblank;
        }
        return 0;
    }

    if (!(smushRules & SM_SMUSH)) {
        /* Universal smush: just return the right char */
        return right;
    }

    /* SMUSH_EQUAL: same char */
    if (smushRules & SM_EQUAL) {
        if (left == right && !(hardblank && left == hardblank)) return left;
    }

    /* SMUSH_UNDERSCORE: _ smushed with hierarchy chars */
    if (smushRules & SM_UNDERSCORE) {
        static const char *us = "|/\\[]{}()<>";
        if (left == '_' && strchr(us, right)) return right;
        if (right == '_' && strchr(us, left)) return left;
    }

    /* SMUSH_HIERARCHY: hierarchy of chars |> /\ []{}() <> */
    if (smushRules & SM_HIERARCHY) {
        static const char *classes[] = {"|", "/\\", "[]", "{}", "()", "<>", NULL};
        int leftClass = -1, rightClass = -1;
        for (int i = 0; classes[i]; i++) {
            if (strchr(classes[i], left)) leftClass = i;
            if (strchr(classes[i], right)) rightClass = i;
        }
        if (leftClass >= 0 && rightClass >= 0 && leftClass != rightClass) {
            return (leftClass > rightClass) ? left : right;
        }
    }

    /* SMUSH_PAIR: pair of brackets */
    if (smushRules & SM_PAIR) {
        if ((left == '[' && right == ']') || (left == ']' && right == '[')) return '|';
        if ((left == '{' && right == '}') || (left == '}' && right == '{')) return '|';
        if ((left == '(' && right == ')') || (left == ')' && right == '(')) return '|';
    }

    /* SMUSH_BIGX: / and \ become X */
    if (smushRules & SM_BIGX) {
        if (left == '/' && right == '\\') return '|';
        if (left == '\\' && right == '/') return 'Y';
        if (left == '>' && right == '<') return 'X';
    }

    return 0; /* can't smush */
}

/* The output buffer for a line */
typedef struct {
    char **rows;     /* height rows */
    int *rowLens;    /* current allocated length of each row */
    int width;       /* current total width */
    int height;
    char hardblank;
} OutputBuf;

static OutputBuf *createOutputBuf(int height, char hardblank) {
    OutputBuf *buf = malloc(sizeof(OutputBuf));
    buf->height = height;
    buf->hardblank = hardblank;
    buf->width = 0;
    buf->rows = malloc(height * sizeof(char *));
    buf->rowLens = malloc(height * sizeof(int));
    for (int i = 0; i < height; i++) {
        buf->rows[i] = malloc(MAX_LINE_LEN);
        buf->rows[i][0] = 0;
        buf->rowLens[i] = MAX_LINE_LEN;
    }
    return buf;
}

static void freeOutputBuf(OutputBuf *buf) {
    if (!buf) return;
    for (int i = 0; i < buf->height; i++) free(buf->rows[i]);
    free(buf->rows);
    free(buf->rowLens);
    free(buf);
}

static void clearOutputBuf(OutputBuf *buf) {
    buf->width = 0;
    for (int i = 0; i < buf->height; i++) buf->rows[i][0] = 0;
}

/* Ensure row has at least 'width' chars, padded with spaces */
static void padRow(char *row, int width) {
    int len = strlen(row);
    for (int i = len; i < width; i++) row[i] = ' ';
    row[width] = 0;
}

/* Calculate maximum smush amount between current buffer and next figchar */
static int calcSmushAmount_proper(OutputBuf *buf, FigChar *fc, int layout, FigFont *font) {
    if (layout == -1) return 1; /* full width */

    int maxAmnt = fc->width + buf->width;
    int amnt = maxAmnt;

    for (int row = 0; row < buf->height; row++) {
        const char *bLine = buf->rows[row];
        const char *cLine = fc->lines[row] ? fc->lines[row] : "";
        int bLen = strlen(bLine);
        int cLen = strlen(cLine);

        /* Find how far right we can push */
        int rowAmnt = 0;
        int limit = bLen + cLen;

        for (int i = 0; i <= limit; i++) {
            /* Try overlapping by i+1 */
            /* Left char at position bLen-(i+1) */
            int lPos = bLen - (i + 1);
            char lc = (lPos >= 0) ? bLine[lPos] : ' ';
            if (font->hardblank && lc == font->hardblank) lc = ' ';

            /* Right char at position 0+i... wait, for right char we look at position i from left */
            /* Actually: when overlapping by n, left's last n chars overlap with right's first n chars */
            /* For position offset i (0-based), left's col is bLen-1-i from end = bLen-(n) + (n-1-i) */
            /* This is getting complex - let me think differently */
            /* When overlap=n: left column = bLen-n+j, right column = j, for j=0..n-1 */
            /* We want max n such that for all rows and all j, can smush left[bLen-n+j] with right[j] */
            break;
        }

        /* Simple approach: find rightmost non-space in left, leftmost non-space in right */
        int lEdge = bLen - 1;
        while (lEdge >= 0 && (bLine[lEdge] == ' ' || (font->hardblank && bLine[lEdge] == font->hardblank))) lEdge--;

        int rEdge = 0;
        while (rEdge < cLen && (cLine[rEdge] == ' ' || (font->hardblank && cLine[rEdge] == font->hardblank))) rEdge++;

        /* Space between right edge of left and left edge of right (when at full width) */
        int space = bLen - lEdge - 1 + rEdge;

        if (space < amnt) amnt = space;

        /* Check if smushing could give us one more */
        if (layout & SM_SMUSH) {
            /* Check if the first collision can be smushed */
            if (lEdge >= 0 && rEdge < cLen) {
                char lc = bLine[lEdge];
                char rc = cLine[rEdge];
                if (font->hardblank && lc == font->hardblank) lc = ' ';
                if (font->hardblank && rc == font->hardblank) rc = ' ';
                if (smushChars(lc, rc, font->hardblank, layout) != 0) {
                    /* Can smush one more */
                    if (space + 1 < amnt) amnt = space + 1; /* don't increase */
                    /* Actually this checks if THIS row allows one more overlap */
                }
            }
        }

        (void)rowAmnt;
    }

    if (amnt < 0) amnt = 0;
    return amnt;
}

