            f=fopen(path,"r"); if(f){if(outpath)strncpy(outpath,path,pathmax);return f;}
            snprintf(path,sizeof(path),"%s/%s.tlf",dir,name);
            f=fopen(path,"r"); if(f){if(outpath)strncpy(outpath,path,pathmax);return f;}
        }
    }
    /* Try current dir */
    if (hasExt) {
        f=fopen(name,"r"); if(f){if(outpath)strncpy(outpath,name,pathmax);return f;}
    } else {
        snprintf(path,sizeof(path),"%s.flf",name);
        f=fopen(path,"r"); if(f){if(outpath)strncpy(outpath,path,pathmax);return f;}
        snprintf(path,sizeof(path),"%s.tlf",name);
        f=fopen(path,"r"); if(f){if(outpath)strncpy(outpath,path,pathmax);return f;}
    }
    return NULL;
}

static Font *loadFont(const char *dir, const char *name) {
    FILE *f = openFont(dir, name, NULL, 0);
    if (!f) return NULL;

    char header[MAXROW];
    if (readLine(f, header, MAXROW) < 0) { fclose(f); return NULL; }

    Font *font = calloc(1, sizeof(Font));
    int isTlf = 0;
    if (strncmp(header,"flf2",4)==0) isTlf=0;
    else if (strncmp(header,"tlf2",4)==0) isTlf=1;
    else { fprintf(stderr,"%s: Not a FIGlet 2 font file\n",name); free(font); fclose(f); return NULL; }
    font->isTlf = isTlf;

    char *p = header + 4;
    if (*p == 'a') p++;
    if (!isTlf) {
        font->hardblank = *p++;
        if (*p == ' ') p++;
    } else {
        font->hardblank = 0;
        if (*p == ' ') p++;
    }

    /* Parse: height baseline maxLen oldLayout commentLines [printDir [fullLayout [codeTagCount]]] */
    font->height = (int)strtol(p, &p, 10); while(*p==' ')p++;
    font->baseline = (int)strtol(p, &p, 10); while(*p==' ')p++;
    font->maxLength = (int)strtol(p, &p, 10); while(*p==' ')p++;
    font->oldLayout = (int)strtol(p, &p, 10); while(*p==' ')p++;
    int commentLines = (int)strtol(p, &p, 10); while(*p==' ')p++;
    font->printDir = 0;
    if (*p) { font->printDir = (int)strtol(p, &p, 10); while(*p==' ')p++; }
    font->fullLayout = 0;
    if (*p) { font->fullLayout = (int)strtol(p, &p, 10); while(*p==' ')p++; }
    font->codeTagCount = 0;
    if (*p) { font->codeTagCount = (int)strtol(p, &p, 10); }

    /* Skip comment lines */
    char line[MAXROW];
    for (int i = 0; i < commentLines; i++) readLine(f, line, MAXROW);

    /* Standard 95 ASCII chars (32-126) */
    for (int ch = 32; ch <= 126; ch++) {
        FigChar *fc = readFigChar(f, font->height);
        if (!fc) break;
        font->chars[ch] = fc;
    }
    /* 7 Deutsch chars */
    static const int deutsch[] = {196,214,220,228,246,252,223};
    for (int i = 0; i < 7; i++) {
        FigChar *fc = readFigChar(f, font->height);
        if (!fc) break;
        font->chars[deutsch[i]] = fc;
    }

    /* Code-tagged chars */
    while (1) {
        long pos = ftell(f);
        if (readLine(f, line, MAXROW) < 0) break;
        /* Skip blank lines */
        char *lp = line;
        while (*lp == ' ' || *lp == '\t') lp++;
        if (*lp == 0) continue;
        /* Try to parse as a number */
        char *end = lp;
        long code = strtol(lp, &end, 0);
        if (end == lp || code <= 0 || code >= MAX_CHARS) {
            /* Maybe negative unicode or special; try hex */
            if (lp[0] == '-') {
                code = strtol(lp, &end, 10);
            }
            if (end == lp) { fseek(f, pos, SEEK_SET); break; }
        }
        if (code <= 0 || code >= MAX_CHARS) {
            /* Skip this char */
            for (int r = 0; r < font->height; r++) readLine(f, line, MAXROW);
            continue;
        }
        FigChar *fc = readFigChar(f, font->height);
        if (!fc) break;
        if (font->chars[code]) freeFigChar(font->chars[code]);
        font->chars[code] = fc;
    }

    fclose(f);
    return font;
}

/* ---- Control files ---- */
static int parseEscapeVal(const char *s, long *val) {
    if (!s || !*s) return 0;
    if (s[0] == '\\') {
        if (s[1] == '0' && (s[2]=='x'||s[2]=='X')) {
            char *e; *val = strtol(s+3, &e, 16); return (int)(e-s);
        }
        if (s[1] == '-' || isdigit((unsigned char)s[1])) {
            char *e; *val = strtol(s+1, &e, 10); return (int)(e-s);
        }
        *val = (unsigned char)s[1]; return 2;
    }
    unsigned char c = (unsigned char)s[0];
    if (c < 0x80) { *val = c; return 1; }
    if (c < 0xE0) { *val = ((c&0x1F)<<6)|((unsigned char)s[1]&0x3F); return 2; }
    if (c < 0xF0) { *val = ((c&0x0F)<<12)|(((unsigned char)s[1]&0x3F)<<6)|((unsigned char)s[2]&0x3F); return 3; }
    *val = ((c&7)<<18)|(((unsigned char)s[1]&0x3F)<<12)|(((unsigned char)s[2]&0x3F)<<6)|((unsigned char)s[3]&0x3F); return 4;
}

static CtrlFile *loadCtrlFile(const char *filename) {
    /* Try to open */
    FILE *f = NULL;
    char path[1024];
    f = fopen(filename, "r");
    if (!f) {
        snprintf(path,sizeof(path),"%s.flc",filename);
        f = fopen(path,"r");
    }
    if (!f && fontDir && fontDir[0]) {
        snprintf(path,sizeof(path),"%s/%s",fontDir,filename);
        f = fopen(path,"r");
        if (!f) {
            snprintf(path,sizeof(path),"%s/%s.flc",fontDir,filename);
            f = fopen(path,"r");
        }
    }
    if (!f) return NULL;

    CtrlFile *cf = calloc(1, sizeof(CtrlFile));
    char line[MAXROW];
    int first = 1;
    while (readLine(f, line, MAXROW) >= 0) {
        if (first) {
            first = 0;
            if (strncmp(line,"flc2",4)==0) continue;
        }
        char *p = line;
        while (*p==' '||*p=='\t') p++;
        if (!*p || *p=='#') continue;

        if (*p == 'f') continue; /* freeze */
        if (*p == 'u') { cf->utf8mode = 1; continue; }
        if (*p == 'h') { cf->hzmode = 1; continue; }
        if (*p == 'g') continue; /* ISO2022 - skip */

        /* Tab-separated format: 0xXX \t 0xXXXX */
        if (p[0]=='0' && (p[1]=='x'||p[1]=='X')) {
            char *tab = strchr(p, '\t');
            if (tab) {
                long src = strtol(p, NULL, 16);
                long dst = strtol(tab+1, NULL, 16);
                if (src > 0 && dst >= 0) {
                    TEntry *e = malloc(sizeof(TEntry));
                    e->src = src; e->dst = dst; e->next = cf->entries; cf->entries = e;
                }
            }
            continue;
        }

        if (*p == 't') {
            p++; while(*p==' '||*p=='\t')p++;
            long s0, s1, d0, d1; int len;
            len = parseEscapeVal(p, &s0); if (!len) continue; p += len;
            s1 = s0;
            if (*p == '-') { p++; len = parseEscapeVal(p, &s1); p += len; }
            while(*p==' '||*p=='\t')p++;
            if (!*p) continue;
            len = parseEscapeVal(p, &d0); p += len;
            d1 = d0;
            if (*p == '-') { p++; len = parseEscapeVal(p, &d1); p += len; }
            (void)d1;
            if (s0 == s1) {
                TEntry *e = malloc(sizeof(TEntry));
                e->src = s0; e->dst = d0; e->next = cf->entries; cf->entries = e;
            } else {
                TRange *r = malloc(sizeof(TRange));
                r->s0=s0; r->s1=s1; r->d0=d0; r->next=cf->ranges; cf->ranges=r;
            }
        }
    }
    fclose(f);
    return cf;
}

static long applyCtrl(long cp) {
    for (int i = 0; i < numCtrlFiles; i++) {
        CtrlFile *cf = ctrlFiles[i];
        for (TEntry *e = cf->entries; e; e = e->next)
            if (e->src == cp) return e->dst;
        for (TRange *r = cf->ranges; r; r = r->next)
            if (cp >= r->s0 && cp <= r->s1) return r->d0 + (cp - r->s0);
    }
    return cp;
}

/* ---- Smush logic ---- */

/* Get figchar display rows (strip common leading spaces, pad to display width) */
static void getFigCharDisplay(FigChar *fc, char hardblank, char **out_rows, int *out_width) {
    int height = fc->height;
    /* Find min leading spaces across non-blank rows */
    int min_lead = 999999;
    for (int r = 0; r < height; r++) {
        const char *row = fc->row[r];
        if (!row) continue;
        int hasContent = 0;
        for (int j = 0; row[j]; j++) {
            if (row[j] != ' ' && !(hardblank && row[j] == hardblank)) { hasContent = 1; break; }
        }
        if (!hasContent) continue;
        int lead = 0;
        while (row[lead] == ' ') lead++;
        if (lead < min_lead) min_lead = lead;
    }
    if (min_lead == 999999) min_lead = 0;

    /* Strip leading and find display width */
    int disp_width = 0;
    for (int r = 0; r < height; r++) {
        const char *row = fc->row[r] ? fc->row[r] : "";
        const char *stripped = row + (min_lead < (int)strlen(row) ? min_lead : (int)strlen(row));
        /* rstrip length */
        int len = strlen(stripped);
        while (len > 0 && stripped[len-1] == ' ') len--;
        if (len > disp_width) disp_width = len;
    }

    /* Build output rows padded to disp_width */
    for (int r = 0; r < height; r++) {
        const char *row = fc->row[r] ? fc->row[r] : "";
        int rowlen = strlen(row);
        int skip = (min_lead < rowlen) ? min_lead : rowlen;
        const char *stripped = row + skip;
        int slen = strlen(stripped);
        /* rstrip */
        int rlen = slen;
        while (rlen > 0 && stripped[rlen-1] == ' ') rlen--;
        out_rows[r] = malloc(disp_width + 2);
        memcpy(out_rows[r], stripped, rlen);
        for (int j = rlen; j < disp_width; j++) out_rows[r][j] = ' ';
        out_rows[r][disp_width] = 0;
    }
    *out_width = disp_width;
}

static int rightmostNonspace(const char *s, char hardblank) {
    int len = strlen(s);
    for (int i = len-1; i >= 0; i--)
        if (s[i] != ' ' && !(hardblank && s[i] == hardblank)) return i;
    return -1;
}

static int leftmostNonspace(const char *s, char hardblank) {
    for (int i = 0; s[i]; i++)
        if (s[i] != ' ' && !(hardblank && s[i] == hardblank)) return i;
    return strlen(s);
}

static const char *smushHierarchy[] = {"|", "/\\", "[]", "{}", "()", "<>", NULL};

static char smushChars(char lc, char rc, char hardblank, int rules) {
    if (lc == ' ') return rc;
    if (rc == ' ') return lc;
    if (hardblank) {
        if (lc == hardblank && rc == hardblank) {
            return (rules & SM_HARDBLANK) ? hardblank : 0;
        }
        if (lc == hardblank || rc == hardblank) {
            return (rules & SM_HARDBLANK) ? hardblank : 0;
        }
    }
    if (!(rules & SM_SMUSH)) {
        /* Universal smush: right char wins */
        return rc;
    }
    if ((rules & SM_EQUAL) && lc == rc) return lc;
    if (rules & SM_UNDERSCORE) {
        const char *us = "|/\\[]{}()<>";
        if (lc=='_' && strchr(us,rc)) return rc;
        if (rc=='_' && strchr(us,lc)) return lc;
    }
    if (rules & SM_HIERARCHY) {
        int lclass=-1, rclass=-1;
        for (int i = 0; smushHierarchy[i]; i++) {
            if (strchr(smushHierarchy[i],lc)) lclass=i;
            if (strchr(smushHierarchy[i],rc)) rclass=i;
        }
        if (lclass>=0 && rclass>=0 && lclass!=rclass)
            return (lclass>rclass)?lc:rc;
    }
    if (rules & SM_PAIR) {
        if ((lc=='['&&rc==']')||(lc==']'&&rc=='[')) return '|';
        if ((lc=='{'&&rc=='}')||(lc=='}'&&rc=='{')) return '|';
        if ((lc=='('&&rc==')')||(lc==')'&&rc=='(')) return '|';
    }
    if (rules & SM_BIGX) {
        if (lc=='/'&&rc=='\\') return '|';
        if (lc=='\\'&&rc=='/') return 'Y';
        if (lc=='>'&&rc=='<') return 'X';
    }
    return 0;
}

/* Layout mode struct */
typedef struct {
    int mode;      /* LM_FULL_WIDTH, LM_KERN, LM_SMUSH, LM_OVERLAP */
    int rules;     /* smush rules (SM_*) */
    char hardblank;
} Layout;

/* Compute effective layout from font + options */
static Layout getLayout(Font *font) {
    Layout lay;
    lay.hardblank = font->hardblank;

    /* Determine effective smush mode */
    int fl = font->fullLayout;
    /* If smushOverride is set by user */
    if (smushOverride == -99) {
        /* Use font default */
        /* fullLayout: bit 7 = smush active, bit 6 = kern, bits 0-5 = rules */
        if (fl & SM_SMUSH) {
            /* Smushing */
            int rules = fl & 63;
            if (rules == 0) {
                lay.mode = LM_OVERLAP;
                lay.rules = 0;
            } else {
                lay.mode = LM_SMUSH;
                lay.rules = rules | SM_SMUSH;
            }
        } else if (fl & SM_KERN) {
            lay.mode = LM_KERN;
            lay.rules = 0;
        } else {
            /* No info: use oldLayout */
            int ol = font->oldLayout;
            if (ol == -1) { lay.mode = LM_FULL_WIDTH; lay.rules = 0; }
            else if (ol == 0) { lay.mode = LM_KERN; lay.rules = 0; }
            else {
                lay.mode = LM_SMUSH;
                lay.rules = ol | SM_SMUSH;
            }
        }
        return lay;
    }

    /* User override */
    if (smushOverride == -1) { /* -W full width */
        lay.mode = LM_FULL_WIDTH; lay.rules = 0; return lay;
    }
    if (smushOverride == 0) { /* -k kern */
        lay.mode = LM_KERN; lay.rules = 0; return lay;
    }
    if (smushOverride == -2) { /* -s: use font default but force smush */
        /* Same as font default but treat kern-only fonts as smush */
        if (fl & SM_SMUSH) {
            int rules = fl & 63;
            if (rules == 0) { lay.mode = LM_OVERLAP; lay.rules = 0; }
            else { lay.mode = LM_SMUSH; lay.rules = rules | SM_SMUSH; }
        } else {
            int ol = font->oldLayout;
            if (ol < 0) { lay.mode = LM_FULL_WIDTH; lay.rules = 0; }
            else if (ol == 0) { lay.mode = LM_KERN; lay.rules = 0; }
            else { lay.mode = LM_SMUSH; lay.rules = ol | SM_SMUSH; }
        }
        return lay;
    }
    if (smushOverride == -3) { /* -S: force smush with font rules */
        int rules;
        if (fl & SM_SMUSH) rules = fl & 63;
        else if (font->oldLayout > 0) rules = font->oldLayout;
        else rules = 0;
        if (rules == 0) { lay.mode = LM_OVERLAP; lay.rules = 0; }
        else { lay.mode = LM_SMUSH; lay.rules = rules | SM_SMUSH; }
        return lay;
    }
    if (smushOverride == -4) { /* -o overlap */
        lay.mode = LM_OVERLAP; lay.rules = 0; return lay;
    }
    if (smushOverride == -5) { /* -n no smush (same as -W) */
        lay.mode = LM_FULL_WIDTH; lay.rules = 0; return lay;
    }
    /* smushOverride is explicit -m N */
    lay.rules = smushOverride | SM_SMUSH;
    if ((smushOverride & 63) == 0) { lay.mode = LM_OVERLAP; lay.rules = 0; }
    else lay.mode = LM_SMUSH;
    return lay;
}

/* Compute smush amount between left buffer (rows of left_width) and right figchar */
static int computeSmushAmt(char **leftRows, int leftWidth, int height,
                           char **rightRows, int rightWidth,
                           Layout *lay) {
    if (lay->mode == LM_FULL_WIDTH) return 0; /* actually add 0 extra space? no, add nothing */

    /* For full-width: no kern, just concatenate */
    /* kern amount = total whitespace between leftmost non-space of right and rightmost of left */
    int kern = leftWidth + rightWidth; /* max possible */
    for (int r = 0; r < height; r++) {
        const char *L = leftRows[r] ? leftRows[r] : "";
        const char *R = rightRows[r] ? rightRows[r] : "";
        int rm = rightmostNonspace(L, lay->hardblank);
        int lm = leftmostNonspace(R, lay->hardblank);
        int ll = strlen(L);
        int gap;
        if (rm < 0) gap = ll + lm;
        else gap = (ll - rm - 1) + lm;
        if (gap < kern) kern = gap;
    }

    if (lay->mode == LM_KERN) return kern;

    /* Smush: try one more */
    /* Check all rows at overlap = kern+1 */
    int can_smush = 1;
    int overlap = kern + 1;
    for (int r = 0; r < height; r++) {
        const char *L = leftRows[r] ? leftRows[r] : "";
        const char *R = rightRows[r] ? rightRows[r] : "";
        int ll = strlen(L);
        int rl = strlen(R);
        for (int j = 0; j < overlap; j++) {
            int lpos = ll - overlap + j;
            char lc = (lpos >= 0 && lpos < ll) ? L[lpos] : ' ';
            char rc = (j < rl) ? R[j] : ' ';
            if (lc == ' ' || (lay->hardblank && lc == lay->hardblank && rc == ' ')) continue;
            if (rc == ' ' || (lay->hardblank && rc == lay->hardblank && lc == ' ')) continue;
            /* Both non-space - try smush */
            char sc = smushChars(lc, rc, lay->hardblank, lay->rules);
            if (!sc) { can_smush = 0; break; }
        }
        if (!can_smush) break;
    }
    return can_smush ? overlap : kern;
}

/* Output buffer */
typedef struct {
    char **rows;
    int width;
    int height;
    char hardblank;
    int capacity;
} OutBuf;

static OutBuf *createBuf(int height, char hardblank) {
    OutBuf *b = calloc(1, sizeof(OutBuf));
    b->height = height;
    b->hardblank = hardblank;
    b->width = 0;
    b->capacity = MAXROW;
    b->rows = malloc(height * sizeof(char*));
    for (int i = 0; i < height; i++) {
        b->rows[i] = calloc(1, MAXROW);
    }
    return b;
}

static void freeBuf(OutBuf *b) {
    if (!b) return;
    for (int i = 0; i < b->height; i++) free(b->rows[i]);
    free(b->rows);
    free(b);
}

static void clearBuf(OutBuf *b) {
    b->width = 0;
    for (int i = 0; i < b->height; i++) b->rows[i][0] = 0;
}

/* Ensure row is at least 'width' chars, padded with spaces */
static void ensureWidth(char *row, int width) {
    int len = strlen(row);
    for (int i = len; i < width; i++) row[i] = ' ';
    row[width] = 0;
}

/* Append a figchar to the output buffer */
static void appendChar(OutBuf *buf, FigChar *fc, Layout *lay) {
    /* Get figchar rows in appropriate mode */
    int height = buf->height;
    char **fcRows = malloc(height * sizeof(char*));
    int fcWidth;

    if (lay->mode == LM_FULL_WIDTH) {
        /* Use original rows */
        fcWidth = fc->width;
        for (int r = 0; r < height; r++) {
            const char *row = (r < fc->height && fc->row[r]) ? fc->row[r] : "";
            fcRows[r] = strdup(row);
        }
    } else {
        /* Use display rows */
        getFigCharDisplay(fc, lay->hardblank, fcRows, &fcWidth);
    }

    /* Compute smush amount */
    int smushAmt;
    if (buf->width == 0) {
        smushAmt = 0;
    } else {
        /* Build leftRows from buffer (right-aligned part we need) */
        smushAmt = computeSmushAmt(buf->rows, buf->width, height, fcRows, fcWidth, lay);
    }

    /* Apply smush: merge fcRows into buf->rows at offset (buf->width - smushAmt) */
    int newWidth = buf->width + fcWidth - smushAmt;
    if (newWidth < 0) newWidth = 0;

    for (int r = 0; r < height; r++) {
        /* Ensure buffer row is at least buf->width wide */
        ensureWidth(buf->rows[r], buf->width);

        /* Apply overlap */
        const char *fc_row = fcRows[r];
        int fcLen = strlen(fc_row);
        for (int j = 0; j < fcLen; j++) {
            int bpos = buf->width - smushAmt + j;
            char nc = fc_row[j];
            if (bpos >= buf->capacity - 1) break;
            if (bpos < buf->width) {
                /* Overlap region */
                char bc = buf->rows[r][bpos];
                if (bc == ' ' || (lay->hardblank && bc == lay->hardblank && nc != ' ')) {
                    buf->rows[r][bpos] = nc;
                } else if (nc != ' ') {
                    char sc = smushChars(bc, nc, lay->hardblank, lay->rules);
                    if (sc) buf->rows[r][bpos] = sc;
                    /* else keep bc */
                }
            } else {
                buf->rows[r][bpos] = nc;
            }
        }
        buf->rows[r][newWidth > buf->capacity-1 ? buf->capacity-1 : newWidth] = 0;
    }
    buf->width = newWidth;

    for (int r = 0; r < height; r++) free(fcRows[r]);
    free(fcRows);
}

/* Get effective smush width for word-wrap check */
static int charSmushWidth(OutBuf *buf, FigChar *fc, Layout *lay) {
    int height = buf->height;
    char **fcRows = malloc(height * sizeof(char*));
    int fcWidth;
    if (lay->mode == LM_FULL_WIDTH) {
        fcWidth = fc->width;
        for (int r = 0; r < height; r++) {
            const char *row = (r < fc->height && fc->row[r]) ? fc->row[r] : "";
            fcRows[r] = strdup(row);
        }
    } else {
        getFigCharDisplay(fc, lay->hardblank, fcRows, &fcWidth);
    }
    int smushAmt;
    if (buf->width == 0) smushAmt = 0;
    else smushAmt = computeSmushAmt(buf->rows, buf->width, height, fcRows, fcWidth, lay);
    int res = fcWidth - smushAmt;
    for (int r = 0; r < height; r++) free(fcRows[r]);
    free(fcRows);
    return res;
}

/* Print the output buffer */
static void printBuf(OutBuf *buf, int justify, int width, int rtl) {
    /* Find actual content width (max rstrip length) */
    int contentWidth = 0;
    for (int r = 0; r < buf->height; r++) {
        int len = strlen(buf->rows[r]);
        while (len > 0 && buf->rows[r][len-1] == ' ') len--;
        if (len > contentWidth) contentWidth = len;
    }

    /* If rtl, reverse each row */
    /* (not implementing full RTL for now - just reverse the order of chars in display) */

    /* Determine justification */
    int just = justify;
    if (just < 0) {
        /* auto: left for LTR, right for RTL */
        just = rtl ? 2 : 0;
    }

    for (int r = 0; r < buf->height; r++) {
        char *row = buf->rows[r];
        int len = strlen(row);
        /* rstrip */
        while (len > 0 && row[len-1] == ' ') len--;
        row[len] = 0;

        /* Replace hardblank with space */
        char hb = buf->hardblank;
        if (hb) {
            for (int j = 0; j < len; j++)
                if (row[j] == hb) row[j] = ' ';
        }

        if (just == 1) {
            /* center */
            int pad = (width - contentWidth) / 2;
            if (pad < 0) pad = 0;
            for (int j = 0; j < pad; j++) putchar(' ');
            /* rstrip again after hardblank replacement */
            len = strlen(row);
            while (len > 0 && row[len-1] == ' ') len--;
            fwrite(row, 1, len, stdout);
        } else if (just == 2) {
            /* right */
            int pad = width - contentWidth;
            if (pad < 0) pad = 0;
            for (int j = 0; j < pad; j++) putchar(' ');
            len = strlen(row);
            while (len > 0 && row[len-1] == ' ') len--;
            fwrite(row, 1, len, stdout);
        } else {
            /* left */
            fwrite(row, 1, len, stdout);
        }
        putchar('\n');
    }
}

/* Print and clear buffer */
static void flushBuf(OutBuf *buf, int justify, int width, int rtl) {
    /* Check if buffer has any non-space content */
    int hasContent = 0;
    for (int r = 0; r < buf->height && !hasContent; r++) {
        char *row = buf->rows[r];
        for (int j = 0; row[j]; j++) {
            if (row[j] != ' ' && !(buf->hardblank && row[j] == buf->hardblank)) {
                hasContent = 1; break;
            }
        }
    }
    if (!hasContent && buf->width == 0) return;
    printBuf(buf, justify, width, rtl);
    clearBuf(buf);
}

/* Read a UTF-8 codepoint from a string; return bytes consumed */
static int readUTF8(const unsigned char *s, long *cp) {
    unsigned char c = s[0];
    if (c == 0) { *cp = 0; return 0; }
    if (c < 0x80) { *cp = c; return 1; }
    if (c < 0xE0) {
        if (!s[1]) { *cp = c; return 1; }
        *cp = ((c&0x1F)<<6)|((unsigned char)s[1]&0x3F); return 2;
    }
    if (c < 0xF0) {
        if (!s[1]||!s[2]) { *cp = c; return 1; }
        *cp = ((c&0x0F)<<12)|(((unsigned char)s[1]&0x3F)<<6)|((unsigned char)s[2]&0x3F); return 3;
    }
    if (!s[1]||!s[2]||!s[3]) { *cp = c; return 1; }
    *cp = ((c&7)<<18)|(((unsigned char)s[1]&0x3F)<<12)|(((unsigned char)s[2]&0x3F)<<6)|((unsigned char)s[3]&0x3F);
    return 4;
}

/* German mode: translate [ \ ] { | } ~ */
static long germanTranslate(long cp) {
    switch(cp) {
    case '[': return 0xC4; /* Ä */
    case '\\': return 0xD6; /* Ö */
    case ']': return 0xDC; /* Ü */
    case '{': return 0xE4; /* ä */
    case '|': return 0xF6; /* ö */
    case '}': return 0xFC; /* ü */
    case '~': return 0xDF; /* ß */
    default: return cp;
    }
}

/* Process one line of text */
static void processLine(const char *line, OutBuf *buf, Layout *lay, int justify, int rtl) {
    const unsigned char *p = (const unsigned char *)line;
    while (*p) {
        long cp;
        int n = readUTF8(p, &cp);
        if (n <= 0) break;
        p += n;

        /* Tab -> space */
        if (cp == '\t') cp = ' ';
        /* Form-feed, vertical-tab, carriage-return -> newline */
        if (cp == '\f' || cp == '\v' || cp == '\r') {
            flushBuf(buf, justify, outputWidth, rtl);
            continue;
        }

        /* German mode */
        if (germanMode) cp = germanTranslate(cp);
        /* Control file translation */
        cp = applyCtrl(cp);

        /* Find figchar */
        FigChar *fc = NULL;
        if (cp >= 0 && cp < MAX_CHARS) fc = theFont->chars[cp];
        if (!fc && cp >= 0x20 && cp <= 0x7e) {
            /* Use space as fallback? No, just skip unknown chars */
        }
        if (!fc) continue;

        /* Word wrap: check if adding this char would exceed output width */
        /* Only break at spaces when width would be exceeded */
        int addWidth = charSmushWidth(buf, fc, lay);
        if (outputWidth > 1 && buf->width + addWidth > outputWidth) {
            /* Need to break */
            flushBuf(buf, justify, outputWidth, rtl);
        }

        appendChar(buf, fc, lay);
    }
}

/* Process text with word-wrap */
static void processLineWordWrap(const char *line, OutBuf *buf, Layout *lay, int justify, int rtl) {
    /* Split on spaces, try to fit words */
    const unsigned char *p = (const unsigned char *)line;
    OutBuf *wordBuf = createBuf(buf->height, buf->hardblank);

    while (*p) {
        /* Get next word (sequence of non-space chars, or a single space) */
        if (*p == ' ') {
            /* space character */
            long cp = ' ';
            cp = applyCtrl(cp);
            FigChar *fc = (cp < MAX_CHARS && cp >= 0) ? theFont->chars[cp] : NULL;
            if (fc) {
                /* Try to add space */
                int addWidth = charSmushWidth(buf, fc, lay);
                if (outputWidth > 1 && buf->width + addWidth > outputWidth) {
                    flushBuf(buf, justify, outputWidth, rtl);
                } else {
                    appendChar(buf, fc, lay);
                }
            }
            p++;
        } else {
            /* Non-space: collect a word into wordBuf */
            clearBuf(wordBuf);
            const unsigned char *wordStart = p;
            while (*p && *p != ' ') {
                long cp; int n = readUTF8(p, &cp); p += n;
                if (germanMode) cp = germanTranslate(cp);
                cp = applyCtrl(cp);
                FigChar *fc = (cp >= 0 && cp < MAX_CHARS) ? theFont->chars[cp] : NULL;
                if (fc) appendChar(wordBuf, fc, lay);
            }
            /* Does word fit with current buffer? */
            if (buf->width == 0) {
                /* Empty buffer: just dump word (even if oversized) */
                for (int r = 0; r < buf->height; r++) {
                    free(buf->rows[r]);
                    buf->rows[r] = strdup(wordBuf->rows[r]);
                }
                buf->width = wordBuf->width;
            } else {
                /* Check if word fits */
                /* Compute smush amount between buf and wordBuf */
                int smushAmt = computeSmushAmt(buf->rows, buf->width, buf->height,
                                               wordBuf->rows, wordBuf->width, lay);
                int combinedWidth = buf->width + wordBuf->width - smushAmt;
                if (outputWidth > 1 && combinedWidth > outputWidth) {
                    /* Flush and start new line with word */
                    flushBuf(buf, justify, outputWidth, rtl);
                    for (int r = 0; r < buf->height; r++) {
                        free(buf->rows[r]);
                        buf->rows[r] = strdup(wordBuf->rows[r]);
                    }
                    buf->width = wordBuf->width;
                } else {
                    /* Merge wordBuf into buf */
                    for (int r = 0; r < buf->height; r++) {
                        ensureWidth(buf->rows[r], buf->width);
                        const char *wrow = wordBuf->rows[r];
                        int wlen = strlen(wrow);
                        for (int j = 0; j < wlen; j++) {
                            int bpos = buf->width - smushAmt + j;
                            char nc = wrow[j];
                            if (bpos < buf->width) {
                                char bc = buf->rows[r][bpos];
                                if (bc == ' ') buf->rows[r][bpos] = nc;
                                else if (nc != ' ') {
                                    char sc = smushChars(bc, nc, lay->hardblank, lay->rules);
                                    if (sc) buf->rows[r][bpos] = sc;
                                }
                            } else {
                                if (bpos < MAXROW-1) buf->rows[r][bpos] = nc;
                            }
                        }
                        buf->rows[r][combinedWidth] = 0;
                    }
                    buf->width = combinedWidth;
                }
            }
            (void)wordStart;
        }
    }
    freeBuf(wordBuf);
}

static void printVersion(const char *progname) {
