int main(int argc, char **argv) {
    char *progname = argv[0];
    /* Remove path from progname */
    char *slash = strrchr(progname, '/');
    if (slash) progname = slash + 1;

    /* Check FIGLET_FONTDIR environment variable */
    fontDir = getenv("FIGLET_FONTDIR");
    if (!fontDir) fontDir = "";
    fontName = DEFAULT_FONT;

    /* Parse options */
    int i;
    for (i = 1; i < argc; i++) {
        if (argv[i][0] != '-') break;
        if (strcmp(argv[i], "--") == 0) { i++; break; }
        char *opt = argv[i] + 1;
        while (*opt) {
            switch (*opt) {
            case 'f':
                if (opt[1]) { fontName = opt+1; opt += strlen(opt)-1; }
                else if (++i < argc) fontName = argv[i];
                break;
            case 'd':
                if (opt[1]) { fontDir = opt+1; opt += strlen(opt)-1; }
                else if (++i < argc) fontDir = argv[i];
                break;
            case 'c': justMode = 1; break;
            case 'l': justMode = 0; break;
            case 'r': justMode = 2; break;
            case 'x': justMode = -1; break;
            case 'k': smushOverride = 0; break;
            case 'W': smushOverride = -1; break;
            case 'o': smushOverride = -4; break;
            case 's': smushOverride = -2; break;
            case 'S': smushOverride = -3; break;
            case 'n': smushOverride = -5; break;
            case 'p': paragraphMode = 1; break;
            case 'L': printDirOverride = 0; break;
            case 'R': printDirOverride = 1; break;
            case 'X': printDirOverride = -1; break;
            case 'D': germanMode = 1; break;
            case 'E': germanMode = 0; break;
            case 'N': 
                for (int j = 0; j < numCtrlFiles; j++) free(ctrlFiles[j]);
                numCtrlFiles = 0;
                break;
            case 't': {
                struct winsize ws;
                if (ioctl(1, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0)
                    outputWidth = ws.ws_col;
                break;
            }
            case 'w':
                if (opt[1]) { outputWidth = atoi(opt+1); opt += strlen(opt)-1; }
                else if (++i < argc) outputWidth = atoi(argv[i]);
                break;
            case 'm': {
                int mv;
                if (opt[1]) { mv = atoi(opt+1); opt += strlen(opt)-1; }
                else if (++i < argc) mv = atoi(argv[i]);
                else mv = 0;
                if (mv == 0) smushOverride = 0; /* -k */
                else if (mv == -1) smushOverride = -1; /* -W */
                else if (mv == -2) smushOverride = -2; /* -s */
                else smushOverride = mv; /* explicit smush rules */
                break;
            }
            case 'C':
                if (numCtrlFiles < 63) {
                    char *cname;
                    if (opt[1]) { cname = opt+1; opt += strlen(opt)-1; }
                    else if (++i < argc) cname = argv[i];
                    else break;
                    CtrlFile *cf = loadCtrlFile(cname);
                    if (cf) ctrlFiles[numCtrlFiles++] = cf;
                    else fprintf(stderr, "%s: %s: Unable to open control file\n", progname, cname);
                }
                break;
            case 'I': {
                int ic;
                if (opt[1]) { ic = atoi(opt+1); opt += strlen(opt)-1; }
                else if (++i < argc) ic = atoi(argv[i]);
                else ic = 0;
                infoCode = ic;
                break;
            }
            case 'v': infoCode = 0; break;
            case 'A': break; /* obsolete: input from command line - default behavior */
            default: break;
            }
            opt++;
        }
    }

    /* Handle info codes */
    if (infoCode >= 0) {
        switch (infoCode) {
        case -1: break; /* normal */
        case 0:
            printVersion(progname);
            return 0;
        case 1:
            printf("%d\n", FIGLET_VERSION_INT);
            return 0;
        case 2:
            printf("%s\n", fontDir && fontDir[0] ? fontDir : ".");
            return 0;
        case 3:
            printf("%s\n", fontName);
            return 0;
        case 4:
            printf("%d\n", outputWidth);
            return 0;
        case 5:
            printf("flf2 tlf2\n");
            return 0;
        default:
            return 0; /* Other positive values: just exit */
        }
    }

    /* Load font */
    theFont = loadFont(fontDir, fontName);
    if (!theFont) {
