    Layout lay = getLayout(theFont);

    /* Determine print direction */
    int rtl = (printDirOverride >= 0) ? printDirOverride : theFont->printDir;
    /* For auto justify (-x): left for LTR, right for RTL */
    int justify = justMode;
    if (justify < 0) justify = rtl ? 2 : 0;

    /* Create output buffer */
    OutBuf *buf = createBuf(theFont->height, theFont->hardblank);

    /* Process input */
    if (i < argc) {
        /* Input from command line args */
        for (int j = i; j < argc; j++) {
            if (j > i) {
                /* Between args: treated as space? No, each arg is processed separately */
            }
            const char *arg = argv[j];
            if (arg[0] == 0) {
                /* Empty arg = line break */
                flushBuf(buf, justify, outputWidth, rtl);
