                struct winsize ws;
                if (ioctl(1, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0)
                    outputWidth = ws.ws_col;
                break;
            }
            case 'w':
                if (opt[1]) { outputWidth = atoi(opt+1); opt += strlen(opt)-1; }
                else if (++i < argc) outputWidth = atoi(argv[i]);
                break;
            case 'm': {
                int mv;
                if (opt[1]) { mv = atoi(opt+1); opt += strlen(opt)-1; }
                else if (++i < argc) mv = atoi(argv[i]);
                else mv = 0;
                if (mv == 0) smushOverride = 0; /* -k */
                else if (mv == -1) smushOverride = -1; /* -W */
                else if (mv == -2) smushOverride = -2; /* -s */
                else smushOverride = mv; /* explicit smush rules */
                break;
