                else if (++i < argc) ic = atoi(argv[i]);
                else ic = 0;
                infoCode = ic;
                break;
            }
            case 'v': infoCode = 0; break;
            case 'A': break; /* obsolete: input from command line - default behavior */
            default: break;
            }
            opt++;
        }
    }

    /* Handle info codes */
    if (infoCode >= 0) {
        switch (infoCode) {
        case -1: break; /* normal */
        case 0:
            printVersion(progname);
