        }
        flushBuf(buf, justify, outputWidth, rtl);
    } else {
        /* Read from stdin */
        char line[MAXROW * 4];
        char prevLine[MAXROW * 4] = "";
        int hasPrev = 0;

        if (paragraphMode) {
            /* Paragraph mode: join lines unless blank line or next starts with space */
            char combined[MAXROW * 16] = "";
            while (fgets(line, sizeof(line), stdin)) {
                int len = strlen(line);
                /* Strip trailing newline */
                while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) line[--len] = 0;

                if (len == 0) {
                    /* Blank line = paragraph break */
                    if (combined[0]) {
                        processLineWordWrap(combined, buf, &lay, justify, rtl);
                        flushBuf(buf, justify, outputWidth, rtl);
                        combined[0] = 0;
                    }
                    /* Output blank line (height rows) */
                    for (int r = 0; r < theFont->height; r++) putchar('\n');
                } else if (line[0] == ' ' || line[0] == '\t') {
                    /* Starts with space = new paragraph */
                    if (combined[0]) {
                        processLineWordWrap(combined, buf, &lay, justify, rtl);
                        flushBuf(buf, justify, outputWidth, rtl);
                        combined[0] = 0;
                    }
                    processLineWordWrap(line, buf, &lay, justify, rtl);
                    flushBuf(buf, justify, outputWidth, rtl);
                } else {
                    /* Normal line: join with previous */
                    if (combined[0]) {
                        strncat(combined, " ", sizeof(combined)-strlen(combined)-1);
                    }
                    strncat(combined, line, sizeof(combined)-strlen(combined)-1);
                }
            }
            if (combined[0]) {
                processLineWordWrap(combined, buf, &lay, justify, rtl);
                flushBuf(buf, justify, outputWidth, rtl);
            }
        } else {
            /* Normal mode: each line -> output */
            while (fgets(line, sizeof(line), stdin)) {
                int len = strlen(line);
                while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) line[--len] = 0;
