int main(int argc, char **argv) {
    char *progname = argv[0];
    /* Remove path from progname */
    char *slash = strrchr(progname, '/');
    if (slash) progname = slash + 1;

    /* Check FIGLET_FONTDIR environment variable */
    fontDir = getenv("FIGLET_FONTDIR");
    if (!fontDir) fontDir = "";
    fontName = DEFAULT_FONT;

    /* Parse options */
    int i;
    for (i = 1; i < argc; i++) {
        if (argv[i][0] != '-') break;
        if (strcmp(argv[i], "--") == 0) { i++; break; }
        char *opt = argv[i] + 1;
        while (*opt) {
            switch (*opt) {
            case 'f':
                if (opt[1]) { fontName = opt+1; opt += strlen(opt)-1; }
                else if (++i < argc) fontName = argv[i];
                break;
            case 'd':
                if (opt[1]) { fontDir = opt+1; opt += strlen(opt)-1; }
                else if (++i < argc) fontDir = argv[i];
                break;
            case 'c': justMode = 1; break;
            case 'l': justMode = 0; break;
            case 'r': justMode = 2; break;
            case 'x': justMode = -1; break;
            case 'k': smushOverride = 0; break;
            case 'W': smushOverride = -1; break;
            case 'o': smushOverride = -4; break;
            case 's': smushOverride = -2; break;
            case 'S': smushOverride = -3; break;
            case 'n': smushOverride = -5; break;
            case 'p': paragraphMode = 1; break;
            case 'L': printDirOverride = 0; break;
            case 'R': printDirOverride = 1; break;
            case 'X': printDirOverride = -1; break;
            case 'D': germanMode = 1; break;
            case 'E': germanMode = 0; break;
            case 'N': 
                for (int j = 0; j < numCtrlFiles; j++) free(ctrlFiles[j]);
                numCtrlFiles = 0;
                break;
            case 't': {
                struct winsize ws;
                if (ioctl(1, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0)
                    outputWidth = ws.ws_col;
                break;
            }
            case 'w':
                if (opt[1]) { outputWidth = atoi(opt+1); opt += strlen(opt)-1; }
                else if (++i < argc) outputWidth = atoi(argv[i]);
                break;
            case 'm': {
                int mv;
                if (opt[1]) { mv = atoi(opt+1); opt += strlen(opt)-1; }
                else if (++i < argc) mv = atoi(argv[i]);
                else mv = 0;
                if (mv == 0) smushOverride = 0; /* -k */
                else if (mv == -1) smushOverride = -1; /* -W */
                else if (mv == -2) smushOverride = -2; /* -s */
                else smushOverride = mv; /* explicit smush rules */
                break;
            }
            case 'C':
                if (numCtrlFiles < 63) {
                    char *cname;
                    if (opt[1]) { cname = opt+1; opt += strlen(opt)-1; }
                    else if (++i < argc) cname = argv[i];
                    else break;
                    CtrlFile *cf = loadCtrlFile(cname);
                    if (cf) ctrlFiles[numCtrlFiles++] = cf;
                    else fprintf(stderr, "%s: %s: Unable to open control file\n", progname, cname);
                }
                break;
            case 'I': {
                int ic;
                if (opt[1]) { ic = atoi(opt+1); opt += strlen(opt)-1; }
                else if (++i < argc) ic = atoi(argv[i]);
                else ic = 0;
                infoCode = ic;
                break;
            }
            case 'v': infoCode = 0; break;
            case 'A': break; /* obsolete: input from command line - default behavior */
            default: break;
            }
            opt++;
        }
    }

    /* Handle info codes */
    if (infoCode >= 0) {
        switch (infoCode) {
        case -1: break; /* normal */
        case 0:
            printVersion(progname);
            return 0;
        case 1:
            printf("%d\n", FIGLET_VERSION_INT);
            return 0;
        case 2:
            printf("%s\n", fontDir && fontDir[0] ? fontDir : ".");
            return 0;
        case 3:
            printf("%s\n", fontName);
            return 0;
        case 4:
            printf("%d\n", outputWidth);
            return 0;
        case 5:
            printf("flf2 tlf2\n");
            return 0;
        default:
            return 0; /* Other positive values: just exit */
        }
    }

    /* Load font */
    theFont = loadFont(fontDir, fontName);
    if (!theFont) {
        fprintf(stderr, "%s: %s: Unable to open font file\n", progname, fontName);
        return 1;
    }

    /* Determine layout */
    Layout lay = getLayout(theFont);

    /* Determine print direction */
    int rtl = (printDirOverride >= 0) ? printDirOverride : theFont->printDir;
    /* For auto justify (-x): left for LTR, right for RTL */
    int justify = justMode;
    if (justify < 0) justify = rtl ? 2 : 0;

    /* Create output buffer */
    OutBuf *buf = createBuf(theFont->height, theFont->hardblank);

    /* Process input */
    if (i < argc) {
        /* Input from command line args */
        for (int j = i; j < argc; j++) {
            if (j > i) {
                /* Between args: treated as space? No, each arg is processed separately */
            }
            const char *arg = argv[j];
            if (arg[0] == 0) {
                /* Empty arg = line break */
                flushBuf(buf, justify, outputWidth, rtl);
                /* Print blank line (font height rows) */
                for (int r = 0; r < theFont->height; r++) putchar('\n');
                continue;
            }
            /* Check for newline chars in arg */
            processLineWordWrap(arg, buf, &lay, justify, rtl);
            /* Process newlines in the arg */
            const char *nl;
            /* Actually args don't normally have newlines, but just in case */
        }
        flushBuf(buf, justify, outputWidth, rtl);
    } else {
        /* Read from stdin */
        char line[MAXROW * 4];
        char prevLine[MAXROW * 4] = "";
        int hasPrev = 0;

        if (paragraphMode) {
            /* Paragraph mode: join lines unless blank line or next starts with space */
            char combined[MAXROW * 16] = "";
            while (fgets(line, sizeof(line), stdin)) {
                int len = strlen(line);
                /* Strip trailing newline */
                while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) line[--len] = 0;

                if (len == 0) {
                    /* Blank line = paragraph break */
                    if (combined[0]) {
                        processLineWordWrap(combined, buf, &lay, justify, rtl);
                        flushBuf(buf, justify, outputWidth, rtl);
                        combined[0] = 0;
                    }
                    /* Output blank line (height rows) */
                    for (int r = 0; r < theFont->height; r++) putchar('\n');
                } else if (line[0] == ' ' || line[0] == '\t') {
                    /* Starts with space = new paragraph */
                    if (combined[0]) {
                        processLineWordWrap(combined, buf, &lay, justify, rtl);
                        flushBuf(buf, justify, outputWidth, rtl);
                        combined[0] = 0;
                    }
                    processLineWordWrap(line, buf, &lay, justify, rtl);
                    flushBuf(buf, justify, outputWidth, rtl);
                } else {
                    /* Normal line: join with previous */
                    if (combined[0]) {
                        strncat(combined, " ", sizeof(combined)-strlen(combined)-1);
                    }
                    strncat(combined, line, sizeof(combined)-strlen(combined)-1);
                }
            }
            if (combined[0]) {
                processLineWordWrap(combined, buf, &lay, justify, rtl);
                flushBuf(buf, justify, outputWidth, rtl);
            }
        } else {
            /* Normal mode: each line -> output */
            while (fgets(line, sizeof(line), stdin)) {
                int len = strlen(line);
                while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) line[--len] = 0;
                /* Handle tab as space, etc. */
                processLineWordWrap(line, buf, &lay, justify, rtl);
                flushBuf(buf, justify, outputWidth, rtl);
            }
        }
        (void)prevLine; (void)hasPrev;
    }

    freeBuf(buf);
    freeFont(theFont);
    return 0;
}
