static int readLine(FILE *f, char *buf, int max) {
    int c, i = 0;
    while ((c = fgetc(f)) != EOF) {
        if (c == '\r') { c = fgetc(f); if (c != '\n' && c != EOF) ungetc(c,f); break; }
        if (c == '\n') break;
        if (i < max-1) buf[i++] = (char)c;
    }
    if (c == EOF && i == 0) return -1;
    buf[i] = 0; return i;
}

static void freeFigChar(FigChar *fc) {
    if (!fc) return;
    for (int i = 0; i < fc->height; i++) free(fc->row[i]);
    free(fc->row); free(fc);
}

static FigChar *readFigChar(FILE *f, int height) {
    FigChar *fc = calloc(1, sizeof(FigChar));
    fc->height = height;
    fc->row = calloc(height+1, sizeof(char*));
    char line[MAXROW];
    for (int r = 0; r < height; r++) {
        if (readLine(f, line, MAXROW) < 0) { freeFigChar(fc); return NULL; }
        int len = strlen(line);
        while (len > 0 && line[len-1] == '@') line[--len] = 0;
        fc->row[r] = strdup(line);
        if (len > fc->width) fc->width = len;
    }
    return fc;
}

static Font *loadFont(const char *dir, const char *name) {
    FILE *f = NULL;
