        long pos = ftell(f);
        if (readLine(f, line, MAXROW) < 0) break;
        char *lp = line;
        while (*lp==' '||*lp=='\t') lp++;
        if (!*lp) continue;
        char *end = lp;
        long code = strtol(lp, &end, 0);
        if (end == lp || code <= 0 || code >= MAX_CHARS) { fseek(f,pos,SEEK_SET); break; }
        FigChar *fc = readFigChar(f, font->height);
        if (!fc) break;
        if (font->chars[code]) freeFigChar(font->chars[code]);
        font->chars[code] = fc;
    }
    fclose(f);
    return font;
}

static int parseEscVal(const char *s, long *val) {
    if (!s||!*s) return 0;
    if (s[0]=='\\') {
        if (s[1]=='0'&&(s[2]=='x'||s[2]=='X')) { char *e; *val=strtol(s+3,&e,16); return (int)(e-s); }
        if (s[1]=='-'||isdigit((unsigned char)s[1])) { char *e; *val=strtol(s+1,&e,10); return (int)(e-s); }
        *val=(unsigned char)s[1]; return 2;
    }
    unsigned char c=(unsigned char)s[0];
    if (c<0x80){*val=c;return 1;}
    if (c<0xE0){if(!s[1]){*val=c;return 1;}*val=((c&0x1F)<<6)|((unsigned char)s[1]&0x3F);return 2;}
    if (c<0xF0){if(!s[1]||!s[2]){*val=c;return 1;}*val=((c&0x0F)<<12)|(((unsigned char)s[1]&0x3F)<<6)|((unsigned char)s[2]&0x3F);return 3;}
    if(!s[1]||!s[2]||!s[3]){*val=c;return 1;}
    *val=((c&7)<<18)|(((unsigned char)s[1]&0x3F)<<12)|(((unsigned char)s[2]&0x3F)<<6)|((unsigned char)s[3]&0x3F);return 4;
}

static CtrlFile *loadCtrlFile(const char *filename) {
    FILE *f = NULL;
    char path[1024];
    f = fopen(filename,"r");
    if (!f) { snprintf(path,sizeof(path),"%s.flc",filename); f=fopen(path,"r"); }
    if (!f && fontDir && fontDir[0]) {
        snprintf(path,sizeof(path),"%s/%s",fontDir,filename); f=fopen(path,"r");
        if (!f) { snprintf(path,sizeof(path),"%s/%s.flc",fontDir,filename); f=fopen(path,"r"); }
    }
    if (!f) return NULL;

    CtrlFile *cf = calloc(1, sizeof(CtrlFile));
    char line[MAXROW];
    int first=1;
    while (readLine(f, line, MAXROW) >= 0) {
        if (first) { first=0; if (strncmp(line,"flc2",4)==0) continue; }
        char *p=line; while(*p==' '||*p=='\t')p++;
        if (!*p||*p=='#') continue;
        if (*p=='f'||*p=='g') continue;
        if (*p=='u'){cf->utf8=1;continue;}
        if (*p=='h'){cf->hz=1;continue;}
        if (*p=='0'&&(*(p+1)=='x'||*(p+1)=='X')) {
            char *tab=strchr(p,'\t');
            if (tab) {
                long src=strtol(p,NULL,16), dst=strtol(tab+1,NULL,16);
                if (src>0&&dst>=0){TEntry *e=malloc(sizeof(TEntry));e->src=src;e->dst=dst;e->next=cf->entries;cf->entries=e;}
            }
            continue;
        }
        if (*p=='t') {
            p++; while(*p==' '||*p=='\t')p++;
            long s0,s1,d0,d1; int len;
            len=parseEscVal(p,&s0); if(!len)continue; p+=len;
            s1=s0; if(*p=='-'){p++;len=parseEscVal(p,&s1);p+=len;}
            while(*p==' '||*p=='\t')p++; if(!*p)continue;
            len=parseEscVal(p,&d0); p+=len;
            d1=d0; if(*p=='-'){p++;len=parseEscVal(p,&d1);p+=len;}
            (void)d1;
            if (s0==s1) { TEntry *e=malloc(sizeof(TEntry));e->src=s0;e->dst=d0;e->next=cf->entries;cf->entries=e; }
            else { TRange *r=malloc(sizeof(TRange));r->s0=s0;r->s1=s1;r->d0=d0;r->next=cf->ranges;cf->ranges=r; }
        }
    }
    fclose(f); return cf;
}

static long applyCtrl(long cp) {
    for (int i=0;i<numCtrlFiles;i++) {
        CtrlFile *cf=ctrlFiles[i];
        for (TEntry *e=cf->entries;e;e=e->next) if(e->src==cp) return e->dst;
        for (TRange *r=cf->ranges;r;r=r->next) if(cp>=r->s0&&cp<=r->s1) return r->d0+(cp-r->s0);
    }
    return cp;
}

/* Smush a pair of chars */
static const char *hier[] = {"|", "/\\", "[]", "{}", "()", "<>", NULL};

static char smushPair(char lc, char rc, char hb, int rules) {
    if (lc==' ') return rc;
    if (rc==' ') return lc;
    if (hb) {
        if (lc==hb&&rc==hb) return (rules&SM_HARDBLANK)?hb:0;
        if (lc==hb||rc==hb) return (rules&SM_HARDBLANK)?hb:0;
    }
    if (!(rules&SM_SMUSH)) return rc; /* universal smush */
    if ((rules&SM_EQUAL)&&lc==rc) return lc;
    if (rules&SM_UNDERSCORE) {
        const char *u="|/\\[]{}()<>";
        if (lc=='_'&&strchr(u,rc)) return rc;
        if (rc=='_'&&strchr(u,lc)) return lc;
    }
    if (rules&SM_HIERARCHY) {
        int lc2=-1,rc2=-1;
        for (int i=0;hier[i];i++){if(strchr(hier[i],lc))lc2=i;if(strchr(hier[i],rc))rc2=i;}
        if (lc2>=0&&rc2>=0&&lc2!=rc2) return lc2>rc2?lc:rc;
    }
    if (rules&SM_PAIR) {
        if ((lc=='['&&rc==']')||(lc==']'&&rc=='[')) return '|';
        if ((lc=='{'&&rc=='}')||(lc=='}'&&rc=='{')) return '|';
        if ((lc=='('&&rc==')')||(lc==')'&&rc=='(')) return '|';
    }
    if (rules&SM_BIGX) {
        if (lc=='/'&&rc=='\\') return '|';
        if (lc=='\\'&&rc=='/') return 'Y';
        if (lc=='>'&&rc=='<') return 'X';
    }
    return 0;
}

/* Effective layout computed from options + font */
typedef struct { int mode; int rules; char hb; } Layout;
/* mode: 0=full-width, 1=kern, 2=smush, 3=overlap */

static Layout getLayout(void) {
    Layout L; L.hb = theFont->hardblank;
    int fl = theFont->fullLayout, ol = theFont->oldLayout;

    if (smushOverride == -1) { L.mode=0; L.rules=0; return L; } /* -W */
    if (smushOverride == 0) { L.mode=1; L.rules=0; return L; }  /* -k */
    if (smushOverride == -4) { L.mode=3; L.rules=0; return L; } /* -o */
    if (smushOverride == -5) { L.mode=0; L.rules=0; return L; } /* -n */

    if (smushOverride >= 1) { /* explicit -m N */
        int r = smushOverride & 63;
        if (r==0) { L.mode=3; L.rules=0; }
        else { L.mode=2; L.rules=r|SM_SMUSH; }
        return L;
    }

    /* -99 = font default, -2 = -s, -3 = -S */
    int use_rules;
    if (fl & SM_SMUSH) {
        use_rules = fl & 63;
    } else if (fl & SM_KERN) {
        if (smushOverride == -3) { /* -S: force smush */
            use_rules = (ol > 0) ? ol : 0;
        } else {
            /* Font wants kern only; -s respects this, -99 too */
            L.mode=1; L.rules=0; return L;
        }
    } else {
        /* No fullLayout info or old-style */
        if (ol < 0) { L.mode=0; L.rules=0; return L; }
        if (ol == 0) { L.mode=1; L.rules=0; return L; }
        use_rules = ol;
    }

    if (smushOverride == -3) { /* -S: force smush even if font wants kern */
        if (!(fl & SM_SMUSH) && (fl & SM_KERN)) {
            use_rules = (ol > 0) ? ol : 0;
        }
    }

    if (use_rules == 0) { L.mode=3; L.rules=0; }
    else { L.mode=2; L.rules=use_rules|SM_SMUSH; }
    return L;
}

/* Get display rows for a figchar:
   Strip common leading spaces, pad all rows to display width.
   Returns allocated array of height strings, sets *dwidth */
static char **getDisplayRows(FigChar *fc, char hb, int height, int *dwidth) {
    /* Find min leading spaces among non-blank rows */
    int ml = MAXROW;
    for (int r=0; r<height; r++) {
        const char *row = (r<fc->height && fc->row[r]) ? fc->row[r] : "";
        int hasContent=0;
        for (int j=0; row[j]; j++) if(row[j]!=' '&&!(hb&&row[j]==hb)){hasContent=1;break;}
        if (!hasContent) continue;
        int lead=0; while(row[lead]==' ') lead++;
        if (lead<ml) ml=lead;
    }
    if (ml==MAXROW) ml=0;

    /* Find display width = max rstrip length after stripping leading */
    int dw=0;
    for (int r=0; r<height; r++) {
        const char *row = (r<fc->height && fc->row[r]) ? fc->row[r] : "";
        int rlen = strlen(row);
        int skip = ml < rlen ? ml : rlen;
        const char *s = row+skip;
        int sl = strlen(s);
        while (sl>0 && s[sl-1]==' ') sl--;
        if (sl>dw) dw=sl;
    }

    char **out = malloc(height * sizeof(char*));
    for (int r=0; r<height; r++) {
        const char *row = (r<fc->height && fc->row[r]) ? fc->row[r] : "";
        int rlen = strlen(row);
        int skip = ml < rlen ? ml : rlen;
        const char *s = row+skip;
        int sl = strlen(s);
        while (sl>0 && s[sl-1]==' ') sl--;
        out[r] = malloc(dw+2);
        memcpy(out[r], s, sl);
        memset(out[r]+sl, ' ', dw-sl);
        out[r][dw] = 0;
    }
    *dwidth = dw;
    return out;
}

static void freeRows(char **rows, int n) {
    for (int i=0;i<n;i++) free(rows[i]);
    free(rows);
}

/* Compute smush amount between left buffer rows and right figchar display rows */
static int computeSmush(char **lrows, int lw, char **rrows, int rw, int height, Layout *lay) {
    if (lay->mode==0) return 0; /* full-width: no smush */

    /* Find min gap (for kern) */
    int kern = lw + rw; /* max possible */
    for (int r=0; r<height; r++) {
        const char *L = lrows[r] ? lrows[r] : "";
        const char *R = rrows[r] ? rrows[r] : "";
        int ll = strlen(L);
        /* rightmost non-space in L */
        int rm=-1;
        for (int j=ll-1;j>=0;j--) if(L[j]!=' '&&!(lay->hb&&L[j]==lay->hb)){rm=j;break;}
        /* leftmost non-space in R */
        int lm=strlen(R);
        for (int j=0;R[j];j++) if(R[j]!=' '&&!(lay->hb&&R[j]==lay->hb)){lm=j;break;}

        int gap;
        if (rm<0) gap = ll + lm; /* left row all spaces */
        else gap = (ll-rm-1) + lm;
        if (gap<kern) kern=gap;
    }

    if (lay->mode==1) return kern; /* kern only */

    /* Smush: try overlap = kern+1 */
    int ov = kern+1;
    int can=1;
    for (int r=0; r<height && can; r++) {
        const char *L = lrows[r] ? lrows[r] : "";
        const char *R = rrows[r] ? rrows[r] : "";
        int ll=strlen(L), rl=strlen(R);
        for (int j=0; j<ov && can; j++) {
            int lpos=ll-ov+j;
            char lc=(lpos>=0&&lpos<ll)?L[lpos]:' ';
            char rc=(j<rl)?R[j]:' ';
            if (lc==' '||(lay->hb&&lc==lay->hb&&rc==' ')) continue;
            if (rc==' '||(lay->hb&&rc==lay->hb&&lc==' ')) continue;
            char sc = smushPair(lc, rc, lay->hb, lay->rules);
            if (!sc) can=0;
        }
    }
    return can ? ov : kern;
}

/* Output line buffer */
typedef struct {
    char **rows;
    int width;
    int height;
    char hb;
} LineBuf;

static LineBuf *newLineBuf(int height, char hb) {
    LineBuf *b = calloc(1,sizeof(LineBuf));
    b->height=height; b->hb=hb;
    b->rows=malloc(height*sizeof(char*));
    for(int i=0;i<height;i++){b->rows[i]=calloc(1,MAXROW);}
    return b;
}
static void freeLineBuf(LineBuf *b){
    if(!b)return;
    for(int i=0;i<b->height;i++)free(b->rows[i]);
    free(b->rows);free(b);
}
static void clearLineBuf(LineBuf *b){
    b->width=0;
    for(int i=0;i<b->height;i++) b->rows[i][0]=0;
}

/* Add a figchar to line buffer using display rows */
static void addChar(LineBuf *buf, char **crow, int cw, int smushAmt, Layout *lay) {
    int neww = buf->width + cw - smushAmt;
    if (neww < 0) neww = 0;

    for (int r=0; r<buf->height; r++) {
        /* Ensure current row padded to buf->width */
        int blen = strlen(buf->rows[r]);
        while (blen < buf->width) buf->rows[r][blen++] = ' ';
        buf->rows[r][buf->width] = 0;

        const char *cr = crow[r] ? crow[r] : "";
        int crlen = strlen(cr);

        for (int j=0; j<crlen; j++) {
            int bpos = buf->width - smushAmt + j;
            if (bpos >= MAXROW-1) break;
            char nc = cr[j];
            if (bpos < buf->width) {
                /* Overlap region */
                char bc = buf->rows[r][bpos];
                if (bc==' ' || (lay->hb&&bc==lay->hb&&nc!=' '&&!(lay->hb&&nc==lay->hb))) {
                    buf->rows[r][bpos] = nc;
                } else if (nc!=' ' && !(lay->hb&&nc==lay->hb)) {
                    char sc = smushPair(bc, nc, lay->hb, lay->rules);
                    if (sc) buf->rows[r][bpos] = sc;
                    /* else keep bc */
                }
            } else {
                buf->rows[r][bpos] = nc;
            }
        }
        /* Null terminate */
        if (neww < MAXROW) buf->rows[r][neww] = 0;
    }
    buf->width = neww;
}

/* Print line buffer and clear */
static void flushLine(LineBuf *buf, int justify, int wrapWidth, int rtl) {
    if (buf->width == 0) {
        /* print empty line */
        for (int r=0; r<buf->height; r++) putchar('\n');
        return;
    }

    /* Find content width = max rstrip length */
    int cw = 0;
    for (int r=0; r<buf->height; r++) {
        char *row = buf->rows[r];
        /* Replace hardblank for measurement */
        int len = strlen(row);
        while (len>0 && (row[len-1]==' '||(buf->hb&&row[len-1]==buf->hb))) len--;
        if (len>cw) cw=len;
    }

    /* Determine padding for justification */
    int pad = 0;
    int just = justify;
    if (just == 1) { /* center */
        pad = (wrapWidth - cw) / 2;
        if (pad < 0) pad = 0;
    } else if (just == 2) { /* right */
        pad = wrapWidth - cw;
        if (pad < 0) pad = 0;
    }

    for (int r=0; r<buf->height; r++) {
        char *row = buf->rows[r];
        /* Replace hardblanks with spaces */
        char hb = buf->hb;
        int len = strlen(row);
        /* Ensure row is cw wide */
        while (len < cw) row[len++] = ' ';
        row[cw] = 0;
        /* Replace hb with space */
        if (hb) for (int j=0; j<cw; j++) if (row[j]==hb) row[j]=' ';

        /* rstrip for actual content */
        int printlen = cw;
        while (printlen>0 && row[printlen-1]==' ') printlen--;

        if (rtl) {
            /* Right-to-left: reverse the row content */
            /* pad from left side */
            int rpad = wrapWidth - cw;
            if (rpad < 0) rpad = 0;
            if (just == 1) rpad = (wrapWidth - cw) / 2;
            else if (just == 0) rpad = wrapWidth - cw;
            else rpad = 0;
            if (rpad < 0) rpad = 0;
            for (int j=0; j<rpad; j++) putchar(' ');
            fwrite(row, 1, printlen, stdout);
        } else {
            for (int j=0; j<pad; j++) putchar(' ');
            fwrite(row, 1, printlen, stdout);
        }
        putchar('\n');
    }

    clearLineBuf(buf);
}

static int readUTF8(const unsigned char *s, long *cp) {
    unsigned char c=s[0];
    if (!c){*cp=0;return 0;}
    if (c<0x80){*cp=c;return 1;}
    if (c<0xE0){if(!s[1]){*cp=c;return 1;}*cp=((c&0x1F)<<6)|((unsigned char)s[1]&0x3F);return 2;}
    if (c<0xF0){if(!s[1]||!s[2]){*cp=c;return 1;}*cp=((c&0x0F)<<12)|(((unsigned char)s[1]&0x3F)<<6)|((unsigned char)s[2]&0x3F);return 3;}
    if(!s[1]||!s[2]||!s[3]){*cp=c;return 1;}
    *cp=((c&7)<<18)|(((unsigned char)s[1]&0x3F)<<12)|(((unsigned char)s[2]&0x3F)<<6)|((unsigned char)s[3]&0x3F);return 4;
}

static long germanChar(long cp) {
    switch(cp){case '[':return 0xC4;case '\\':return 0xD6;case ']':return 0xDC;
               case '{':return 0xE4;case '|':return 0xF6;case '}':return 0xFC;case '~':return 0xDF;}
    return cp;
}

/* Process one word/char and add to linebuf; flush if too wide */
static void addCodepointToLine(long cp, LineBuf *buf, Layout *lay, int justify, int rtl) {
    FigChar *fc = (cp>=0&&cp<MAX_CHARS) ? theFont->chars[cp] : NULL;
    if (!fc) return;

    int dw; char **drows;
    if (lay->mode==0) {
        /* Full-width: use raw rows */
        drows = malloc(buf->height*sizeof(char*));
        for (int r=0;r<buf->height;r++) {
            const char *row=(r<fc->height&&fc->row[r])?fc->row[r]:"";
            drows[r]=strdup(row);
        }
        dw = fc->width;
    } else {
        drows = getDisplayRows(fc, lay->hb, buf->height, &dw);
    }

    int smushAmt = (buf->width==0) ? 0 : computeSmush(buf->rows, buf->width, drows, dw, buf->height, lay);
    int addedWidth = dw - smushAmt;
    int newWidth = buf->width + addedWidth;

    /* Word wrap */
    if (outputWidth > 1 && newWidth > outputWidth && buf->width > 0) {
        flushLine(buf, justify, outputWidth, rtl);
        smushAmt = 0;
        newWidth = dw;
    }

    addChar(buf, drows, dw, smushAmt, lay);
    freeRows(drows, buf->height);
}

static void processText(const char *text, LineBuf *buf, Layout *lay, int justify, int rtl) {
    const unsigned char *p = (const unsigned char *)text;
    while (*p) {
        long cp; int n=readUTF8(p,&cp); if(n<=0)break; p+=n;
        if (cp=='\t') cp=' ';
        if (cp=='\f'||cp=='\v'||cp=='\r') { flushLine(buf,justify,outputWidth,rtl); continue; }
        if (germanMode) cp=germanChar(cp);
        cp=applyCtrl(cp);
        addCodepointToLine(cp, buf, lay, justify, rtl);
    }
}

static void printVersion(const char *prog) {
    printf("FIGlet Copyright (C) 1991-2012 Glenn Chappell, Ian Chai, John Cowan,\n");
    printf("Christiaan Keet and Claudio Matsuoka\n");
    printf("Internet: <info@figlet.org> Version: %s, date: %s\n\n",FIGLET_VERSION,FIGLET_DATE);
    printf("FIGlet, along with the various FIGlet fonts and documentation, may be\n");
    printf("freely copied and distributed.\n\n");
    printf("If you use FIGlet, please send an e-mail message to <info@figlet.org>.\n\n");
    printf("The latest version of FIGlet is available from the web site,\n");
    printf("\thttp://www.figlet.org/\n\n");
    printf("Usage: %s [ -cklnoprstvxDELNRSWX ] [ -d fontdirectory ]\n",prog);
    printf("              [ -f fontfile ] [ -m smushmode ] [ -w outputwidth ]\n");
    printf("              [ -C controlfile ] [ -I infocode ] [ message ]\n");
}

int main(int argc, char **argv) {
    char *progname = argv[0];
    char *sl = strrchr(progname,'/'); if(sl) progname=sl+1;

    const char *envdir = getenv("FIGLET_FONTDIR");
    if (envdir) fontDir = (char*)envdir;
    else fontDir = "";
    fontName = DEFAULT_FONT;

    int i;
    for (i=1; i<argc; i++) {
        if (argv[i][0]!='-') break;
        if (!strcmp(argv[i],"--")){i++;break;}
        char *opt=argv[i]+1;
        while (*opt) {
            char o=*opt;
            switch(o) {
            case 'f': if(opt[1]){fontName=opt+1;opt+=strlen(opt)-1;}else if(++i<argc)fontName=argv[i]; break;
            case 'd': if(opt[1]){fontDir=opt+1;opt+=strlen(opt)-1;}else if(++i<argc)fontDir=argv[i]; break;
            case 'c': justMode=1; break;
            case 'l': justMode=0; break;
            case 'r': justMode=2; break;
            case 'x': justMode=-1; break;
            case 'k': smushOverride=0; break;
            case 'W': smushOverride=-1; break;
            case 'o': smushOverride=-4; break;
            case 's': smushOverride=-2; break;
            case 'S': smushOverride=-3; break;
            case 'n': smushOverride=-5; break;
            case 'p': paragraphMode=1; break;
            case 'L': printDirOverride=0; break;
            case 'R': printDirOverride=1; break;
            case 'X': printDirOverride=-1; break;
            case 'D': germanMode=1; break;
            case 'E': germanMode=0; break;
            case 'N': for(int j=0;j<numCtrlFiles;j++)free(ctrlFiles[j]); numCtrlFiles=0; break;
            case 't': { struct winsize ws; if(ioctl(1,TIOCGWINSZ,&ws)==0&&ws.ws_col>0) outputWidth=ws.ws_col; break; }
            case 'w': if(opt[1]){outputWidth=atoi(opt+1);opt+=strlen(opt)-1;}else if(++i<argc)outputWidth=atoi(argv[i]); break;
            case 'm': { int mv; if(opt[1]){mv=atoi(opt+1);opt+=strlen(opt)-1;}else if(++i<argc)mv=atoi(argv[i]);else mv=0;
                       if(mv==0) smushOverride=0; else if(mv==-1) smushOverride=-1; else if(mv==-2) smushOverride=-2; else smushOverride=mv; break; }
            case 'C': { char *cn; if(opt[1]){cn=opt+1;opt+=strlen(opt)-1;}else if(++i<argc)cn=argv[i];else break;
                       CtrlFile *cf=loadCtrlFile(cn);
                       if(cf){if(numCtrlFiles<MAX_CTRL-1)ctrlFiles[numCtrlFiles++]=cf;}
                       else fprintf(stderr,"%s: %s: Unable to open control file\n",progname,cn); break; }
            case 'I': { int ic; if(opt[1]){ic=atoi(opt+1);opt+=strlen(opt)-1;}else if(++i<argc)ic=atoi(argv[i]);else ic=0; infoCode=ic; break; }
            case 'v': infoCode=0; break;
            case 'A': break;
            default: break;
            }
            opt++;
        }
    }

    if (infoCode >= 0) {
        switch(infoCode) {
        case 0: printVersion(progname); return 0;
        case 1: printf("%d\n",FIGLET_VERSION_INT); return 0;
        case 2: printf("%s\n",fontDir&&fontDir[0]?fontDir:"."); return 0;
