/* Smush a pair of chars */
static const char *hier[] = {"|", "/\\", "[]", "{}", "()", "<>", NULL};

static char smushPair(char lc, char rc, char hb, int rules) {
    if (lc==' ') return rc;
    if (rc==' ') return lc;
    if (hb) {
        if (lc==hb&&rc==hb) return (rules&SM_HARDBLANK)?hb:0;
        if (lc==hb||rc==hb) return (rules&SM_HARDBLANK)?hb:0;
    }
    if (!(rules&SM_SMUSH)) return rc; /* universal smush */
    if ((rules&SM_EQUAL)&&lc==rc) return lc;
    if (rules&SM_UNDERSCORE) {
        const char *u="|/\\[]{}()<>";
        if (lc=='_'&&strchr(u,rc)) return rc;
        if (rc=='_'&&strchr(u,lc)) return lc;
    }
    if (rules&SM_HIERARCHY) {
        int lc2=-1,rc2=-1;
        for (int i=0;hier[i];i++){if(strchr(hier[i],lc))lc2=i;if(strchr(hier[i],rc))rc2=i;}
        if (lc2>=0&&rc2>=0&&lc2!=rc2) return lc2>rc2?lc:rc;
    }
    if (rules&SM_PAIR) {
        if ((lc=='['&&rc==']')||(lc==']'&&rc=='[')) return '|';
        if ((lc=='{'&&rc=='}')||(lc=='}'&&rc=='{')) return '|';
        if ((lc=='('&&rc==')')||(lc==')'&&rc=='(')) return '|';
    }
    if (rules&SM_BIGX) {
        if (lc=='/'&&rc=='\\') return '|';
        if (lc=='\\'&&rc=='/') return 'Y';
        if (lc=='>'&&rc=='<') return 'X';
    }
    return 0;
}

