        for (int i=0;hier[i];i++){if(strchr(hier[i],lc))lc2=i;if(strchr(hier[i],rc))rc2=i;}
        if (lc2>=0&&rc2>=0&&lc2!=rc2) return lc2>rc2?lc:rc;
    }
    if (rules&SM_PAIR) {
        if ((lc=='['&&rc==']')||(lc==']'&&rc=='[')) return '|';
        if ((lc=='{'&&rc=='}')||(lc=='}'&&rc=='{')) return '|';
        if ((lc=='('&&rc==')')||(lc==')'&&rc=='(')) return '|';
    }
    if (rules&SM_BIGX) {
        if (lc=='/'&&rc=='\\') return '|';
        if (lc=='\\'&&rc=='/') return 'Y';
        if (lc=='>'&&rc=='<') return 'X';
    }
    return 0;
}

/* Effective layout computed from options + font */
typedef struct { int mode; int rules; char hb; } Layout;
/* mode: 0=full-width, 1=kern, 2=smush, 3=overlap */

static Layout getLayout(void) {
    Layout L; L.hb = theFont->hardblank;
    int fl = theFont->fullLayout, ol = theFont->oldLayout;

    if (smushOverride == -1) { L.mode=0; L.rules=0; return L; } /* -W */
    if (smushOverride == 0) { L.mode=1; L.rules=0; return L; }  /* -k */
    if (smushOverride == -4) { L.mode=3; L.rules=0; return L; } /* -o */
    if (smushOverride == -5) { L.mode=0; L.rules=0; return L; } /* -n */

    if (smushOverride >= 1) { /* explicit -m N */
        int r = smushOverride & 63;
        if (r==0) { L.mode=3; L.rules=0; }
        else { L.mode=2; L.rules=r|SM_SMUSH; }
        return L;
    }

    /* -99 = font default, -2 = -s, -3 = -S */
    int use_rules;
    if (fl & SM_SMUSH) {
        use_rules = fl & 63;
    } else if (fl & SM_KERN) {
        if (smushOverride == -3) { /* -S: force smush */
            use_rules = (ol > 0) ? ol : 0;
        } else {
            /* Font wants kern only; -s respects this, -99 too */
            L.mode=1; L.rules=0; return L;
        }
    } else {
        /* No fullLayout info or old-style */
        if (ol < 0) { L.mode=0; L.rules=0; return L; }
        if (ol == 0) { L.mode=1; L.rules=0; return L; }
        use_rules = ol;
    }

    if (smushOverride == -3) { /* -S: force smush even if font wants kern */
        if (!(fl & SM_SMUSH) && (fl & SM_KERN)) {
            use_rules = (ol > 0) ? ol : 0;
        }
    }

    if (use_rules == 0) { L.mode=3; L.rules=0; }
    else { L.mode=2; L.rules=use_rules|SM_SMUSH; }
    return L;
}

/* Get display rows for a figchar:
   Strip common leading spaces, pad all rows to display width.
   Returns allocated array of height strings, sets *dwidth */
static char **getDisplayRows(FigChar *fc, char hb, int height, int *dwidth) {
    /* Find min leading spaces among non-blank rows */
    int ml = MAXROW;
    for (int r=0; r<height; r++) {
        const char *row = (r<fc->height && fc->row[r]) ? fc->row[r] : "";
        int hasContent=0;
        for (int j=0; row[j]; j++) if(row[j]!=' '&&!(hb&&row[j]==hb)){hasContent=1;break;}
        if (!hasContent) continue;
        int lead=0; while(row[lead]==' ') lead++;
        if (lead<ml) ml=lead;
    }
    if (ml==MAXROW) ml=0;

    /* Find display width = max rstrip length after stripping leading */
    int dw=0;
    for (int r=0; r<height; r++) {
        const char *row = (r<fc->height && fc->row[r]) ? fc->row[r] : "";
        int rlen = strlen(row);
        int skip = ml < rlen ? ml : rlen;
        const char *s = row+skip;
        int sl = strlen(s);
        while (sl>0 && s[sl-1]==' ') sl--;
        if (sl>dw) dw=sl;
    }

    char **out = malloc(height * sizeof(char*));
    for (int r=0; r<height; r++) {
        const char *row = (r<fc->height && fc->row[r]) ? fc->row[r] : "";
        int rlen = strlen(row);
        int skip = ml < rlen ? ml : rlen;
        const char *s = row+skip;
        int sl = strlen(s);
        while (sl>0 && s[sl-1]==' ') sl--;
        out[r] = malloc(dw+2);
        memcpy(out[r], s, sl);
        memset(out[r]+sl, ' ', dw-sl);
        out[r][dw] = 0;
    }
    *dwidth = dw;
    return out;
}

static void freeRows(char **rows, int n) {
    for (int i=0;i<n;i++) free(rows[i]);
    free(rows);
}

/* Compute smush amount between left buffer rows and right figchar display rows */
static int computeSmush(char **lrows, int lw, char **rrows, int rw, int height, Layout *lay) {
    if (lay->mode==0) return 0; /* full-width: no smush */

    /* Find min gap (for kern) */
    int kern = lw + rw; /* max possible */
    for (int r=0; r<height; r++) {
        const char *L = lrows[r] ? lrows[r] : "";
        const char *R = rrows[r] ? rrows[r] : "";
        int ll = strlen(L);
        /* rightmost non-space in L */
        int rm=-1;
        for (int j=ll-1;j>=0;j--) if(L[j]!=' '&&!(lay->hb&&L[j]==lay->hb)){rm=j;break;}
        /* leftmost non-space in R */
        int lm=strlen(R);
        for (int j=0;R[j];j++) if(R[j]!=' '&&!(lay->hb&&R[j]==lay->hb)){lm=j;break;}

        int gap;
        if (rm<0) gap = ll + lm; /* left row all spaces */
        else gap = (ll-rm-1) + lm;
        if (gap<kern) kern=gap;
    }

    if (lay->mode==1) return kern; /* kern only */

    /* Smush: try overlap = kern+1 */
    int ov = kern+1;
    int can=1;
    for (int r=0; r<height && can; r++) {
        const char *L = lrows[r] ? lrows[r] : "";
        const char *R = rrows[r] ? rrows[r] : "";
        int ll=strlen(L), rl=strlen(R);
        for (int j=0; j<ov && can; j++) {
            int lpos=ll-ov+j;
            char lc=(lpos>=0&&lpos<ll)?L[lpos]:' ';
            char rc=(j<rl)?R[j]:' ';
            if (lc==' '||(lay->hb&&lc==lay->hb&&rc==' ')) continue;
            if (rc==' '||(lay->hb&&rc==lay->hb&&lc==' ')) continue;
            char sc = smushPair(lc, rc, lay->hb, lay->rules);
            if (!sc) can=0;
        }
    }
    return can ? ov : kern;
}

/* Output line buffer */
typedef struct {
    char **rows;
    int width;
    int height;
    char hb;
} LineBuf;

static LineBuf *newLineBuf(int height, char hb) {
    LineBuf *b = calloc(1,sizeof(LineBuf));
    b->height=height; b->hb=hb;
    b->rows=malloc(height*sizeof(char*));
    for(int i=0;i<height;i++){b->rows[i]=calloc(1,MAXROW);}
    return b;
}
static void freeLineBuf(LineBuf *b){
    if(!b)return;
    for(int i=0;i<b->height;i++)free(b->rows[i]);
    free(b->rows);free(b);
}
static void clearLineBuf(LineBuf *b){
    b->width=0;
    for(int i=0;i<b->height;i++) b->rows[i][0]=0;
}

/* Add a figchar to line buffer using display rows */
static void addChar(LineBuf *buf, char **crow, int cw, int smushAmt, Layout *lay) {
    int neww = buf->width + cw - smushAmt;
    if (neww < 0) neww = 0;

    for (int r=0; r<buf->height; r++) {
        /* Ensure current row padded to buf->width */
        int blen = strlen(buf->rows[r]);
        while (blen < buf->width) buf->rows[r][blen++] = ' ';
        buf->rows[r][buf->width] = 0;

        const char *cr = crow[r] ? crow[r] : "";
        int crlen = strlen(cr);

        for (int j=0; j<crlen; j++) {
            int bpos = buf->width - smushAmt + j;
            if (bpos >= MAXROW-1) break;
            char nc = cr[j];
            if (bpos < buf->width) {
                /* Overlap region */
                char bc = buf->rows[r][bpos];
                if (bc==' ' || (lay->hb&&bc==lay->hb&&nc!=' '&&!(lay->hb&&nc==lay->hb))) {
                    buf->rows[r][bpos] = nc;
                } else if (nc!=' ' && !(lay->hb&&nc==lay->hb)) {
                    char sc = smushPair(bc, nc, lay->hb, lay->rules);
                    if (sc) buf->rows[r][bpos] = sc;
                    /* else keep bc */
                }
            } else {
                buf->rows[r][bpos] = nc;
            }
        }
        /* Null terminate */
        if (neww < MAXROW) buf->rows[r][neww] = 0;
    }
    buf->width = neww;
}

/* Print line buffer and clear */
static void flushLine(LineBuf *buf, int justify, int wrapWidth, int rtl) {
    if (buf->width == 0) {
        /* print empty line */
        for (int r=0; r<buf->height; r++) putchar('\n');
        return;
    }

    /* Find content width = max rstrip length */
    int cw = 0;
    for (int r=0; r<buf->height; r++) {
        char *row = buf->rows[r];
        /* Replace hardblank for measurement */
        int len = strlen(row);
        while (len>0 && (row[len-1]==' '||(buf->hb&&row[len-1]==buf->hb))) len--;
        if (len>cw) cw=len;
    }

    /* Determine padding for justification */
    int pad = 0;
    int just = justify;
    if (just == 1) { /* center */
        pad = (wrapWidth - cw) / 2;
        if (pad < 0) pad = 0;
    } else if (just == 2) { /* right */
        pad = wrapWidth - cw;
        if (pad < 0) pad = 0;
    }

    for (int r=0; r<buf->height; r++) {
        char *row = buf->rows[r];
        /* Replace hardblanks with spaces */
        char hb = buf->hb;
        int len = strlen(row);
        /* Ensure row is cw wide */
        while (len < cw) row[len++] = ' ';
        row[cw] = 0;
        /* Replace hb with space */
        if (hb) for (int j=0; j<cw; j++) if (row[j]==hb) row[j]=' ';

        /* rstrip for actual content */
        int printlen = cw;
        while (printlen>0 && row[printlen-1]==' ') printlen--;

        if (rtl) {
            /* Right-to-left: reverse the row content */
            /* pad from left side */
            int rpad = wrapWidth - cw;
            if (rpad < 0) rpad = 0;
            if (just == 1) rpad = (wrapWidth - cw) / 2;
            else if (just == 0) rpad = wrapWidth - cw;
            else rpad = 0;
            if (rpad < 0) rpad = 0;
            for (int j=0; j<rpad; j++) putchar(' ');
            fwrite(row, 1, printlen, stdout);
        } else {
            for (int j=0; j<pad; j++) putchar(' ');
            fwrite(row, 1, printlen, stdout);
        }
        putchar('\n');
    }

    clearLineBuf(buf);
}

static int readUTF8(const unsigned char *s, long *cp) {
    unsigned char c=s[0];
    if (!c){*cp=0;return 0;}
    if (c<0x80){*cp=c;return 1;}
    if (c<0xE0){if(!s[1]){*cp=c;return 1;}*cp=((c&0x1F)<<6)|((unsigned char)s[1]&0x3F);return 2;}
    if (c<0xF0){if(!s[1]||!s[2]){*cp=c;return 1;}*cp=((c&0x0F)<<12)|(((unsigned char)s[1]&0x3F)<<6)|((unsigned char)s[2]&0x3F);return 3;}
    if(!s[1]||!s[2]||!s[3]){*cp=c;return 1;}
    *cp=((c&7)<<18)|(((unsigned char)s[1]&0x3F)<<12)|(((unsigned char)s[2]&0x3F)<<6)|((unsigned char)s[3]&0x3F);return 4;
}

static long germanChar(long cp) {
    switch(cp){case '[':return 0xC4;case '\\':return 0xD6;case ']':return 0xDC;
               case '{':return 0xE4;case '|':return 0xF6;case '}':return 0xFC;case '~':return 0xDF;}
    return cp;
}

/* Process one word/char and add to linebuf; flush if too wide */
static void addCodepointToLine(long cp, LineBuf *buf, Layout *lay, int justify, int rtl) {
    FigChar *fc = (cp>=0&&cp<MAX_CHARS) ? theFont->chars[cp] : NULL;
    if (!fc) return;

    int dw; char **drows;
    if (lay->mode==0) {
        /* Full-width: use raw rows */
        drows = malloc(buf->height*sizeof(char*));
        for (int r=0;r<buf->height;r++) {
            const char *row=(r<fc->height&&fc->row[r])?fc->row[r]:"";
            drows[r]=strdup(row);
        }
        dw = fc->width;
    } else {
        drows = getDisplayRows(fc, lay->hb, buf->height, &dw);
    }

    int smushAmt = (buf->width==0) ? 0 : computeSmush(buf->rows, buf->width, drows, dw, buf->height, lay);
    int addedWidth = dw - smushAmt;
    int newWidth = buf->width + addedWidth;

    /* Word wrap */
    if (outputWidth > 1 && newWidth > outputWidth && buf->width > 0) {
        flushLine(buf, justify, outputWidth, rtl);
        smushAmt = 0;
        newWidth = dw;
    }

    addChar(buf, drows, dw, smushAmt, lay);
    freeRows(drows, buf->height);
}

static void processText(const char *text, LineBuf *buf, Layout *lay, int justify, int rtl) {
    const unsigned char *p = (const unsigned char *)text;
    while (*p) {
        long cp; int n=readUTF8(p,&cp); if(n<=0)break; p+=n;
        if (cp=='\t') cp=' ';
        if (cp=='\f'||cp=='\v'||cp=='\r') { flushLine(buf,justify,outputWidth,rtl); continue; }
        if (germanMode) cp=germanChar(cp);
        cp=applyCtrl(cp);
        addCodepointToLine(cp, buf, lay, justify, rtl);
    }
}

