            case 'w': if(opt[1]){outputWidth=atoi(opt+1);opt+=strlen(opt)-1;}else if(++i<argc)outputWidth=atoi(argv[i]); break;
            case 'm': { int mv; if(opt[1]){mv=atoi(opt+1);opt+=strlen(opt)-1;}else if(++i<argc)mv=atoi(argv[i]);else mv=0;
