    else if(justify==2){pad=outw-1-contentWidth;if(pad<0)pad=0;}
    /* rtl: flip pad logic */
    if(rtl&&justify==0){pad=outw-1-contentWidth;if(pad<0)pad=0;}
    else if(rtl&&justify==2){pad=0;}

