    const char *dot=strrchr(name,'.');
    int hasExt=(dot&&(strcmp(dot,".flf")==0||strcmp(dot,".tlf")==0));
    #define TRY(p) {f=fopen(p,"r");if(f)goto gotfile;}
    if(name[0]=='/'){TRY(name);if(!hasExt){snprintf(path,sizeof(path),"%s.flf",name);TRY(path);snprintf(path,sizeof(path),"%s.tlf",name);TRY(path);}}
    if(dir&&dir[0]){if(hasExt){snprintf(path,sizeof(path),"%s/%s",dir,name);TRY(path);}else{snprintf(path,sizeof(path),"%s/%s.flf",dir,name);TRY(path);snprintf(path,sizeof(path),"%s/%s.tlf",dir,name);TRY(path);}}
    if(hasExt){TRY(name);}else{snprintf(path,sizeof(path),"%s.flf",name);TRY(path);snprintf(path,sizeof(path),"%s.tlf",name);TRY(path);}
    return NULL;
    gotfile:;
    char header[MAXROW];
    if(readLine(f,header,MAXROW)<0){fclose(f);return NULL;}
    int isTlf=0;
    if(strncmp(header,"flf2",4)==0)isTlf=0;
    else if(strncmp(header,"tlf2",4)==0)isTlf=1;
    else{fclose(f);return NULL;}
    Font *font=calloc(1,sizeof(Font));font->isTlf=isTlf;
    char *p=header+4;if(*p=='a')p++;
    if(!isTlf){font->hardblank=*p++;if(*p==' ')p++;}else{font->hardblank=0;if(*p==' ')p++;}
    font->height=(int)strtol(p,&p,10);while(*p==' ')p++;
    font->baseline=(int)strtol(p,&p,10);while(*p==' ')p++;
    font->maxLength=(int)strtol(p,&p,10);while(*p==' ')p++;
    font->oldLayout=(int)strtol(p,&p,10);while(*p==' ')p++;
    int commentLines=(int)strtol(p,&p,10);while(*p==' ')p++;
    font->printDir=0;if(*p){font->printDir=(int)strtol(p,&p,10);while(*p==' ')p++;}
    font->fullLayout=0;if(*p){font->fullLayout=(int)strtol(p,&p,10);while(*p==' ')p++;}
    char line[MAXROW];
    for(int i=0;i<commentLines;i++)readLine(f,line,MAXROW);
    for(int ch=32;ch<=126;ch++){FigChar *fc=readFigChar(f,font->height);if(!fc)break;font->chars[ch]=fc;}
    static const int deutsch[]={196,214,220,228,246,252,223};
    for(int i=0;i<7;i++){FigChar *fc=readFigChar(f,font->height);if(!fc)break;font->chars[deutsch[i]]=fc;}
    while(1){
        long pos=ftell(f);if(readLine(f,line,MAXROW)<0)break;
        char *lp=line;while(*lp==' '||*lp=='\t')lp++;if(!*lp)continue;
        char *end=lp;long code=strtol(lp,&end,0);
        if(end==lp||code<=0||code>=MAX_CHARS){fseek(f,pos,SEEK_SET);break;}
        FigChar *fc=readFigChar(f,font->height);if(!fc)break;
        if(font->chars[code])freeFigChar(font->chars[code]);font->chars[code]=fc;
    }
    fclose(f);return font;
}

static int parseEsc(const char *s,long *v){
    if(!s||!*s)return 0;
    if(s[0]=='\\'){
        if(s[1]=='0'&&(s[2]=='x'||s[2]=='X')){char *e;*v=strtol(s+3,&e,16);return(int)(e-s);}
        if(s[1]=='-'||isdigit((unsigned char)s[1])){char *e;*v=strtol(s+1,&e,10);return(int)(e-s);}
        *v=(unsigned char)s[1];return 2;
    }
    unsigned char c=(unsigned char)s[0];
    if(c<0x80){*v=c;return 1;}
    if(c<0xE0){if(!s[1]){*v=c;return 1;}*v=((c&0x1F)<<6)|((unsigned char)s[1]&0x3F);return 2;}
    if(c<0xF0){if(!s[1]||!s[2]){*v=c;return 1;}*v=((c&0x0F)<<12)|(((unsigned char)s[1]&0x3F)<<6)|((unsigned char)s[2]&0x3F);return 3;}
    if(!s[1]||!s[2]||!s[3]){*v=c;return 1;}
    *v=((c&7)<<18)|(((unsigned char)s[1]&0x3F)<<12)|(((unsigned char)s[2]&0x3F)<<6)|((unsigned char)s[3]&0x3F);return 4;
}

static CtrlFile *loadCtrlFile(const char *filename){
    FILE *f=NULL;char path[1024];
    f=fopen(filename,"r");
    if(!f){snprintf(path,sizeof(path),"%s.flc",filename);f=fopen(path,"r");}
    if(!f&&fontDir&&fontDir[0]){snprintf(path,sizeof(path),"%s/%s",fontDir,filename);f=fopen(path,"r");if(!f){snprintf(path,sizeof(path),"%s/%s.flc",fontDir,filename);f=fopen(path,"r");}}
    if(!f)return NULL;
    CtrlFile *cf=calloc(1,sizeof(CtrlFile));
    char line[MAXROW];int first=1;
    while(readLine(f,line,MAXROW)>=0){
        if(first){first=0;if(strncmp(line,"flc2",4)==0)continue;}
        char *p=line;while(*p==' '||*p=='\t')p++;
        if(!*p||*p=='#')continue;
        if(*p=='f'||*p=='g')continue;
        if(*p=='u'){cf->utf8=1;continue;}
        if(*p=='h'){cf->hz=1;continue;}
        if(*p=='0'&&(*(p+1)=='x'||*(p+1)=='X')){
            char *tab=strchr(p,'\t');
            if(tab){long src=strtol(p,NULL,16),dst=strtol(tab+1,NULL,16);
                if(src>0&&dst>=0){TEntry *e=malloc(sizeof(TEntry));e->src=src;e->dst=dst;e->next=cf->entries;cf->entries=e;}}
            continue;
        }
        if(*p=='t'){
            p++;while(*p==' '||*p=='\t')p++;
            long s0,s1,d0,d1;int len;
            len=parseEsc(p,&s0);if(!len)continue;p+=len;
            s1=s0;if(*p=='-'){p++;len=parseEsc(p,&s1);p+=len;}
            while(*p==' '||*p=='\t')p++;if(!*p)continue;
            len=parseEsc(p,&d0);p+=len;d1=d0;if(*p=='-'){p++;len=parseEsc(p,&d1);p+=len;}(void)d1;
            if(s0==s1){TEntry *e=malloc(sizeof(TEntry));e->src=s0;e->dst=d0;e->next=cf->entries;cf->entries=e;}
            else{TRange *r=malloc(sizeof(TRange));r->s0=s0;r->s1=s1;r->d0=d0;r->next=cf->ranges;cf->ranges=r;}
        }
    }
    fclose(f);return cf;
}

static long applyCtrl(long cp){
    for(int i=0;i<numCtrlFiles;i++){
        CtrlFile *cf=ctrlFiles[i];
        for(TEntry *e=cf->entries;e;e=e->next)if(e->src==cp)return e->dst;
        for(TRange *r=cf->ranges;r;r=r->next)if(cp>=r->s0&&cp<=r->s1)return r->d0+(cp-r->s0);
    }
    return cp;
}

static const char *hier[]={"<>","()","{}","[]","/\\","|",NULL};

static char smushPair(char lc,char rc,char hb,int rules){
    if(lc==' ')return rc;
    if(rc==' ')return lc;
    if(hb){
        if(lc==hb&&rc==hb)return(rules&SM_HARDBLANK)?hb:0;
        if(lc==hb||rc==hb)return(rules&SM_HARDBLANK)?hb:0;
    }
    if(!(rules&SM_SMUSH))return rc;
    if((rules&SM_EQUAL)&&lc==rc)return lc;
    if(rules&SM_UNDERSCORE){const char *u="|/\\[]{}()<>";if(lc=='_'&&strchr(u,rc))return rc;if(rc=='_'&&strchr(u,lc))return lc;}
    if(rules&SM_HIERARCHY){
        int lc2=-1,rc2=-1;
        for(int i=0;hier[i];i++){if(strchr(hier[i],lc))lc2=i;if(strchr(hier[i],rc))rc2=i;}
        if(lc2>=0&&rc2>=0&&lc2!=rc2)return lc2>rc2?lc:rc;
    }
    if(rules&SM_PAIR){
        if((lc=='['&&rc==']')||(lc==']'&&rc=='['))return'|';
        if((lc=='{'&&rc=='}')||(lc=='}'&&rc=='{'))return'|';
        if((lc=='('&&rc==')')||(lc==')'&&rc=='('))return'|';
    }
    if(rules&SM_BIGX){
        if(lc=='/'&&rc=='\\')return'|';
        if(lc=='\\'&&rc=='/')return'Y';
        if(lc=='>'&&rc=='<')return'X';
    }
    return 0;
}

static Layout getLayout(void){
    Layout L;L.hb=theFont->hardblank;
    int fl=theFont->fullLayout,ol=theFont->oldLayout;
    if(smushOverride==-1){L.mode=0;L.rules=0;return L;}
    if(smushOverride==0){L.mode=1;L.rules=0;return L;}
    if(smushOverride==-4){L.mode=3;L.rules=0;return L;}
    if(smushOverride==-5){L.mode=0;L.rules=0;return L;}
    if(smushOverride>=1){int r=smushOverride&63;if(!r){L.mode=3;L.rules=0;}else{L.mode=2;L.rules=r|SM_SMUSH;}return L;}
    /* font default or -s/-S */
    int use_rules;
    if(fl&SM_SMUSH){use_rules=fl&63;}
    else if(fl&SM_KERN){
        if(smushOverride==-3){use_rules=(ol>0)?ol:0;}
        else{L.mode=1;L.rules=0;return L;}
    }
    else{
        if(ol<0){L.mode=0;L.rules=0;return L;}
        if(ol==0){L.mode=1;L.rules=0;return L;}
        use_rules=ol;
    }
    if(!use_rules){L.mode=3;L.rules=0;}
    else{L.mode=2;L.rules=use_rules|SM_SMUSH;}
    return L;
}

/* Get display rows for figchar (strip common leading spaces, pad to display width) */
static char **getDisplayRows(FigChar *fc, char hb, int height, int *dwidth){
    int ml=MAXROW;
    for(int r=0;r<height;r++){
        const char *row=(r<fc->height&&fc->row[r])?fc->row[r]:"";
        /* Count as non-blank if has any non-space char (including hardblank) */
        int hasContent=0;for(int j=0;row[j];j++)if(row[j]!=' '){hasContent=1;break;}
        if(!hasContent)continue;
        int lead=0;while(row[lead]==' ')lead++;if(lead<ml)ml=lead;
    }
    if(ml==MAXROW)ml=0;
    int dw=0;
    for(int r=0;r<height;r++){
        const char *row=(r<fc->height&&fc->row[r])?fc->row[r]:"";
        int rlen=strlen(row),skip=ml<rlen?ml:rlen;
        const char *s=row+skip;int sl=strlen(s);
        while(sl>0&&s[sl-1]==' ')sl--;if(sl>dw)dw=sl;
    }
    char **out=malloc(height*sizeof(char*));
    for(int r=0;r<height;r++){
        const char *row=(r<fc->height&&fc->row[r])?fc->row[r]:"";
        int rlen=strlen(row),skip=ml<rlen?ml:rlen;
        const char *s=row+skip;int sl=strlen(s);
        while(sl>0&&s[sl-1]==' ')sl--;
        out[r]=malloc(dw+2);memcpy(out[r],s,sl);memset(out[r]+sl,' ',dw-sl);out[r][dw]=0;
    }
    *dwidth=dw;return out;
}

static void freeRows(char **rows,int n){for(int i=0;i<n;i++)free(rows[i]);free(rows);}

/* Compute smush amount between left buffer (lw wide rows) and right figchar display rows */
static int computeSmush(char **lrows,int lw,char **rrows,int rw,int height,Layout *lay){
    if(lay->mode==0)return 0;
    int kern=lw+rw;
    for(int r=0;r<height;r++){
        const char *L=lrows[r]?lrows[r]:"",*R=rrows[r]?rrows[r]:"";
        int ll=strlen(L);
        int rm=-1;for(int j=ll-1;j>=0;j--)if(L[j]!=' '){rm=j;break;}
        int lm=strlen(R);for(int j=0;R[j];j++)if(R[j]!=' '){lm=j;break;}
        int gap=(rm<0)?ll+lm:(ll-rm-1)+lm;
        if(gap<kern)kern=gap;
    }
    if(lay->mode==1)return kern;
    int ov=kern+1,can=1;
    for(int r=0;r<height&&can;r++){
        const char *L=lrows[r]?lrows[r]:"",*R=rrows[r]?rrows[r]:"";
        int ll=strlen(L),rl=strlen(R);
        for(int j=0;j<ov&&can;j++){
            int lpos=ll-ov+j;
            char lc=(lpos>=0&&lpos<ll)?L[lpos]:' ',rc=(j<rl)?R[j]:' ';
            if(lc==' ')continue;if(rc==' ')continue;
            char sc=smushPair(lc,rc,lay->hb,lay->rules);if(!sc)can=0;
        }
    }
    return can?ov:kern;
}

typedef struct { char **rows; int width; int height; char hb; } LineBuf;

static LineBuf *newBuf(int h,char hb){
    LineBuf *b=calloc(1,sizeof(LineBuf));b->height=h;b->hb=hb;
    b->rows=malloc(h*sizeof(char*));for(int i=0;i<h;i++)b->rows[i]=calloc(1,MAXROW);
    return b;
}
static void freeBuf(LineBuf *b){if(!b)return;for(int i=0;i<b->height;i++)free(b->rows[i]);free(b->rows);free(b);}
static void clearBuf(LineBuf *b){b->width=0;for(int i=0;i<b->height;i++)b->rows[i][0]=0;}

static void copyBuf(LineBuf *dst, LineBuf *src){
    dst->width=src->width;
    for(int r=0;r<dst->height;r++){
        int len=strlen(src->rows[r]);
        memcpy(dst->rows[r],src->rows[r],len+1);
    }
}

static void addRowsToBuf(LineBuf *buf, char **crow, int cw, int smushAmt, Layout *lay){
    int neww=buf->width+cw-smushAmt;if(neww<0)neww=0;
    for(int r=0;r<buf->height;r++){
        /* Pad current row to buf->width */
        int blen=strlen(buf->rows[r]);
        while(blen<buf->width){buf->rows[r][blen++]=' ';}buf->rows[r][buf->width]=0;
        const char *cr=crow[r]?crow[r]:"";int crlen=strlen(cr);
        for(int j=0;j<crlen;j++){
            int bpos=buf->width-smushAmt+j;if(bpos>=MAXROW-1)break;
            char nc=cr[j];
            if(bpos<buf->width){
                char bc=buf->rows[r][bpos];
                if(bc==' '){buf->rows[r][bpos]=nc;}
                else if(nc!=' '){char sc=smushPair(bc,nc,lay->hb,lay->rules);if(sc)buf->rows[r][bpos]=sc;}
            }else{buf->rows[r][bpos]=nc;}
        }
        if(neww<MAXROW)buf->rows[r][neww]=0;
    }
    buf->width=neww;
}

/* Flush and print line buffer */
static void flushBuf(LineBuf *buf, int justify, int rtl, int outw){
    if(buf->width==0){for(int r=0;r<buf->height;r++)putchar('\n');return;}
    int cw=buf->width;
    /* Find content width = max rstrip */
    int contentWidth=0;
    for(int r=0;r<buf->height;r++){
        char *row=buf->rows[r];char hb=buf->hb;
        int len=strlen(row);while(len<cw){row[len++]=' ';}row[cw]=0;
        /* rstrip (treating hb as space for measurement) */
        int cl=cw;while(cl>0&&(row[cl-1]==' '||(hb&&row[cl-1]==hb)))cl--;
        if(cl>contentWidth)contentWidth=cl;
    }
    /* Pad for justification */
    int pad=0;
    if(justify==1){pad=(outw-contentWidth)/2;if(pad<0)pad=0;}
    else if(justify==2){pad=outw-1-contentWidth;if(pad<0)pad=0;}
    /* rtl: flip pad logic */
    if(rtl&&justify==0){pad=outw-1-contentWidth;if(pad<0)pad=0;}
    else if(rtl&&justify==2){pad=0;}

    for(int r=0;r<buf->height;r++){
        char *row=buf->rows[r];char hb=buf->hb;
        int len=strlen(row);while(len<cw){row[len++]=' ';}row[cw]=0;
        if(hb)for(int j=0;j<cw;j++)if(row[j]==hb)row[j]=' ';
        /* Print pad then row padded to contentWidth */
        for(int j=0;j<pad;j++)putchar(' ');
        /* Print row (first contentWidth chars) */
        for(int j=0;j<contentWidth;j++)putchar(j<cw?row[j]:' ');
        putchar('\n');
    }
    clearBuf(buf);
}

static int readUTF8(const unsigned char *s,long *cp){
    unsigned char c=s[0];if(!c){*cp=0;return 0;}
    if(c<0x80){*cp=c;return 1;}
    if(c<0xE0){if(!s[1]){*cp=c;return 1;}*cp=((c&0x1F)<<6)|((unsigned char)s[1]&0x3F);return 2;}
    if(c<0xF0){if(!s[1]||!s[2]){*cp=c;return 1;}*cp=((c&0x0F)<<12)|(((unsigned char)s[1]&0x3F)<<6)|((unsigned char)s[2]&0x3F);return 3;}
    if(!s[1]||!s[2]||!s[3]){*cp=c;return 1;}
    *cp=((c&7)<<18)|(((unsigned char)s[1]&0x3F)<<12)|(((unsigned char)s[2]&0x3F)<<6)|((unsigned char)s[3]&0x3F);return 4;
}

static long germanChar(long cp){
    switch(cp){case '[':return 0xC4;case '\\':return 0xD6;case ']':return 0xDC;
               case '{':return 0xE4;case '|':return 0xF6;case '}':return 0xFC;case '~':return 0xDF;}
    return cp;
}

/* Add figchar to buffer, returns false if can't add (overflow) */
static int addFigChar(LineBuf *buf, long cp, Layout *lay){
    FigChar *fc=(cp>=0&&cp<MAX_CHARS)?theFont->chars[cp]:NULL;
    if(!fc)return 1;
    char **crow;int cw;
    if(lay->mode==0){
        crow=malloc(buf->height*sizeof(char*));
        for(int r=0;r<buf->height;r++){const char *row=(r<fc->height&&fc->row[r])?fc->row[r]:"";crow[r]=strdup(row);}
        cw=fc->width;
    }else{
        crow=getDisplayRows(fc,lay->hb,buf->height,&cw);
    }
    int sa=(buf->width==0)?0:computeSmush(buf->rows,buf->width,crow,cw,buf->height,lay);
    int neww=buf->width+cw-sa;
    addRowsToBuf(buf,crow,cw,sa,lay);
    freeRows(crow,buf->height);
    (void)neww;
    return 1;
}

/* Compute width increment if we add cp to buf */
static int addWidth(LineBuf *buf, long cp, Layout *lay){
    FigChar *fc=(cp>=0&&cp<MAX_CHARS)?theFont->chars[cp]:NULL;
    if(!fc)return 0;
    char **crow;int cw;
    if(lay->mode==0){
        crow=malloc(buf->height*sizeof(char*));
        for(int r=0;r<buf->height;r++){const char *row=(r<fc->height&&fc->row[r])?fc->row[r]:"";crow[r]=strdup(row);}
        cw=fc->width;
    }else{
        crow=getDisplayRows(fc,lay->hb,buf->height,&cw);
    }
    int sa=(buf->width==0)?0:computeSmush(buf->rows,buf->width,crow,cw,buf->height,lay);
    int res=cw-sa;
    freeRows(crow,buf->height);
    return res;
}

/* Process a line of text with word-aware wrapping */
static void processLine(const char *text, LineBuf *buf, Layout *lay, int justify, int rtl, int outw){
    const unsigned char *p=(const unsigned char *)text;
    while(*p){
        long cp;int n=readUTF8(p,&cp);if(n<=0)break;
        if(cp=='\t')cp=' ';
        if(cp=='\f'||cp=='\v'||cp=='\r'){flushBuf(buf,justify,rtl,outw);p+=n;continue;}
        if(germanMode)cp=germanChar(cp);
        cp=applyCtrl(cp);
        p+=n;

        if(cp==' '){
            /* Space: lookahead to see if next word fits */
            /* Compute width of space char */
            int sw=addWidth(buf,cp,lay);
            /* Find end of next word */
            const unsigned char *q=p;
            /* Build next word's total width */
            LineBuf *trial=newBuf(buf->height,buf->hb);
            copyBuf(trial,buf);
            /* Add space to trial */
            addFigChar(trial,cp,lay);
            /* Add chars of next word to trial */
            const unsigned char *q2=q;
            int word_added=0;
            while(*q2&&*q2!=' '){
                long cp2;int n2=readUTF8(q2,&cp2);
                if(n2<=0)break;
                long cp2t=cp2;
                if(germanMode)cp2t=germanChar(cp2t);
                cp2t=applyCtrl(cp2t);
                addFigChar(trial,cp2t,lay);
                q2+=n2;word_added=1;
            }
            if(!word_added||outw<=1){
                /* No next word or special width: just add space */
                int neww2=buf->width+sw;
                if(outw>1&&neww2>=outw&&buf->width>0){flushBuf(buf,justify,rtl,outw);}
                else addFigChar(buf,cp,lay);
                freeBuf(trial);
            }else{
                /* Check if trial fits */
                if(outw>1&&trial->width>=outw&&buf->width>0){
                    /* Flush without space, start new with next word */
                    flushBuf(buf,justify,rtl,outw);
                    /* Skip spaces (already consuming 1 space from p) */
                    while(*p==' ')p++;
                    /* Process next word */
                    while(*p&&*p!=' '){
                        long cp2;int n2=readUTF8(p,&cp2);if(n2<=0)break;
                        long cp2t=cp2;if(germanMode)cp2t=germanChar(cp2t);cp2t=applyCtrl(cp2t);
                        /* Check for overflow mid-word */
                        int inc=addWidth(buf,cp2t,lay);
                        if(outw>1&&buf->width+inc>=outw&&buf->width>0)flushBuf(buf,justify,rtl,outw);
                        addFigChar(buf,cp2t,lay);
                        p+=n2;
                    }
                    freeBuf(trial);
                }else{
                    /* Fits: use the trial buf directly */
                    for(int r=0;r<buf->height;r++){free(buf->rows[r]);buf->rows[r]=trial->rows[r];trial->rows[r]=NULL;}
                    buf->width=trial->width;
                    freeBuf(trial);
                    /* Skip the next word (already consumed in trial) */
                    while(*p&&*p!=' '){long cp2;int n2=readUTF8(p,&cp2);(void)cp2;p+=n2;}
                }
            }
            (void)sw;
        }else{
            /* Non-space char */
            int inc=addWidth(buf,cp,lay);
            if(outw>1&&buf->width+inc>=outw&&buf->width>0)flushBuf(buf,justify,rtl,outw);
            addFigChar(buf,cp,lay);
        }
    }
}

