int main(int argc,char **argv){
    char *progname=argv[0];char *sl=strrchr(progname,'/');if(sl)progname=sl+1;
    const char *envdir=getenv("FIGLET_FONTDIR");
    fontDir=envdir?(char*)envdir:"";fontName=DEFAULT_FONT;
    int i;
    for(i=1;i<argc;i++){
        if(argv[i][0]!='-')break;if(!strcmp(argv[i],"--")){i++;break;}
        char *opt=argv[i]+1;
        while(*opt){
            char o=*opt;
            switch(o){
            case 'f':if(opt[1]){fontName=opt+1;opt+=strlen(opt)-1;}else if(++i<argc)fontName=argv[i];break;
            case 'd':if(opt[1]){fontDir=opt+1;opt+=strlen(opt)-1;}else if(++i<argc)fontDir=argv[i];break;
            case 'c':justMode=1;break;case 'l':justMode=0;break;case 'r':justMode=2;break;case 'x':justMode=-1;break;
            case 'k':smushOverride=0;break;case 'W':smushOverride=-1;break;case 'o':smushOverride=-4;break;
            case 's':smushOverride=-2;break;case 'S':smushOverride=-3;break;case 'n':smushOverride=-5;break;
            case 'p':paragraphMode=1;break;
            case 'L':printDirOverride=0;break;case 'R':printDirOverride=1;break;case 'X':printDirOverride=-1;break;
            case 'D':germanMode=1;break;case 'E':germanMode=0;break;
            case 'N':for(int j=0;j<numCtrlFiles;j++)free(ctrlFiles[j]);numCtrlFiles=0;break;
            case 't':{struct winsize ws;if(ioctl(1,TIOCGWINSZ,&ws)==0&&ws.ws_col>0)outputWidth=ws.ws_col;break;}
            case 'w':if(opt[1]){outputWidth=atoi(opt+1);opt+=strlen(opt)-1;}else if(++i<argc)outputWidth=atoi(argv[i]);break;
            case 'm':{int mv;if(opt[1]){mv=atoi(opt+1);opt+=strlen(opt)-1;}else if(++i<argc)mv=atoi(argv[i]);else mv=0;
                if(mv==0)smushOverride=0;else if(mv==-1)smushOverride=-1;else if(mv==-2)smushOverride=-2;else smushOverride=mv;break;}
            case 'C':{char *cn;if(opt[1]){cn=opt+1;opt+=strlen(opt)-1;}else if(++i<argc)cn=argv[i];else break;
                CtrlFile *cf=loadCtrlFile(cn);
                if(cf){if(numCtrlFiles<MAX_CTRL-1)ctrlFiles[numCtrlFiles++]=cf;}
                else fprintf(stderr,"%s: %s: Unable to open control file\n",progname,cn);break;}
            case 'I':{int ic;if(opt[1]){ic=atoi(opt+1);opt+=strlen(opt)-1;}else if(++i<argc)ic=atoi(argv[i]);else ic=0;infoCode=ic;break;}
            case 'v':infoCode=0;break;
            case 'A':break;
            default:break;
            }
            opt++;
        }
    }

    if(infoCode>=0){
        switch(infoCode){
        case 0:printVersion(progname);return 0;
        case 1:printf("%d\n",FIGLET_VERSION_INT);return 0;
        case 2:printf("%s\n",fontDir&&fontDir[0]?fontDir:".");return 0;
        case 3:printf("%s\n",fontName);return 0;
        case 4:printf("%d\n",outputWidth);return 0;
        case 5:printf("flf2 tlf2\n");return 0;
        default:return 0;
        }
    }

    theFont=loadFont(fontDir,fontName);
    if(!theFont){fprintf(stderr,"%s: %s: Unable to open font file\n",progname,fontName);return 1;}

    Layout lay=getLayout();
    int rtl=(printDirOverride>=0)?printDirOverride:theFont->printDir;
    int justify=(justMode>=0)?justMode:(rtl?2:0);

    LineBuf *buf=newBuf(theFont->height,theFont->hardblank);

    if(i<argc){
        for(int j=i;j<argc;j++){
            const char *arg=argv[j];
            if(!arg[0]){
                flushBuf(buf,justify,rtl,outputWidth);
                for(int r=0;r<theFont->height;r++)putchar('\n');
                continue;
            }
            processLine(arg,buf,&lay,justify,rtl,outputWidth);
        }
        flushBuf(buf,justify,rtl,outputWidth);
    }else{
        char line[MAXROW*4];
        if(paragraphMode){
            char acc[MAXROW*16]="";
            while(fgets(line,sizeof(line),stdin)){
                int len=strlen(line);while(len>0&&(line[len-1]=='\n'||line[len-1]=='\r'))line[--len]=0;
                if(!len){
                    if(acc[0]){processLine(acc,buf,&lay,justify,rtl,outputWidth);flushBuf(buf,justify,rtl,outputWidth);acc[0]=0;}
                    for(int r=0;r<theFont->height;r++)putchar('\n');
                }else if(line[0]==' '||line[0]=='\t'){
                    if(acc[0]){processLine(acc,buf,&lay,justify,rtl,outputWidth);flushBuf(buf,justify,rtl,outputWidth);acc[0]=0;}
                    processLine(line,buf,&lay,justify,rtl,outputWidth);flushBuf(buf,justify,rtl,outputWidth);
                }else{
                    if(acc[0])strncat(acc," ",sizeof(acc)-strlen(acc)-1);
                    strncat(acc,line,sizeof(acc)-strlen(acc)-1);
                }
            }
            if(acc[0]){processLine(acc,buf,&lay,justify,rtl,outputWidth);flushBuf(buf,justify,rtl,outputWidth);}
        }else{
            while(fgets(line,sizeof(line),stdin)){
                int len=strlen(line);while(len>0&&(line[len-1]=='\n'||line[len-1]=='\r'))line[--len]=0;
                processLine(line,buf,&lay,justify,rtl,outputWidth);
                flushBuf(buf,justify,rtl,outputWidth);
            }
        }
    }
    freeBuf(buf);return 0;
}
