int readLine(FILE *f, char *buf, int max) {
    int c, i = 0;
    while ((c = fgetc(f)) != EOF) {
        if (c == '\r') { c = fgetc(f); if (c != '\n' && c != EOF) ungetc(c, f); break; }
        if (c == '\n') break;
        if (i < max-1) buf[i++] = (char)c;
    }
    if (c == EOF && i == 0) return -1;
    buf[i] = 0; return i;
}

int main() {
    FILE *f = fopen("assets/emboss.tlf", "r");
    char line[4096];
    // Skip header
    readLine(f, line, 4096);
    printf("Header: %s\n", line);
    // Skip 18 comments
    for (int i = 0; i < 18; i++) readLine(f, line, 4096);
    // Read space char (3 rows)
    printf("Space char:\n");
    for (int r = 0; r < 3; r++) {
        readLine(f, line, 4096);
        int len = strlen(line);
        // TLF dynamic endmark: strip last char (all trailing copies)
        if (len > 0) {
            char em = line[len-1];
            while (len > 0 && line[len-1] == em) line[--len] = 0;
        }
        printf("  Row %d: [%d bytes] ", r, len);
        for (int i = 0; i < len; i++) printf("%02x ", (unsigned char)line[i]);
        printf("\n");
    }
    // Read '!' char  
    printf("! char:\n");
    for (int r = 0; r < 3; r++) {
        readLine(f, line, 4096);
        int len = strlen(line);
        if (len > 0) {
            char em = line[len-1];
            while (len > 0 && line[len-1] == em) line[--len] = 0;
        }
        printf("  Row %d: [%d bytes] %s\n", r, len, line);
    }
    fclose(f);
    return 0;
}
EOF
