# This is the fundamental Unicode issue. Let me think about how to handle it:
# 
# For ASCII fonts: byte_len == codepoint_len, so current code works
# For Unicode TLF fonts: byte_len != codepoint_len, need codepoint-based ops
#
# The key functions that need codepoint-aware behavior:
# 1. contentWidth in flushBuf: use codepoints for rstrip
# 2. Row padding: pad with spaces up to CODEPOINT width, not byte width
# 3. Actual print: just print bytes (no change needed)
#
# The simplest approach: add a function that measures codepoint length of a string's rstrip
# and use that for contentWidth calculation
# Then for padding: add spaces up to that many codepoints
# The byte count may differ but each row will have the same number of display columns

# Let me implement cp_strlen (codepoint count) and use it:

with open('figlet3.c', 'r') as f:
    content = f.read()

# Add codepoint-aware functions before flushBuf
cpfunc = '''
/* Count UTF-8 codepoints in a string */
static int cp_strlen(const char *s) {
    int n = 0;
    while (*s) {
        unsigned char c = (unsigned char)*s;
        if ((c & 0xC0) != 0x80) n++;  /* Count non-continuation bytes */
        s++;
    }
    return n;
}

/* Find the end position (in bytes) of the rstripped string (strip trailing spaces/hardblanks) */
static int cp_rstrip_bytes(const char *s, char hb) {
    int last_nonspace_end = 0;
    int i = 0;
    while (s[i]) {
        unsigned char c = (unsigned char)s[i];
        /* Advance one codepoint */
        int cplen = 1;
        if (c >= 0xF0) cplen = 4;
        else if (c >= 0xE0) cplen = 3;
        else if (c >= 0xC0) cplen = 2;
        /* Check if this codepoint is a space or hardblank */
        int is_space = 0;
        if (cplen == 1 && (s[i] == ' ' || (hb && s[i] == hb))) is_space = 1;
        if (!is_space) last_nonspace_end = i + cplen;
        i += cplen;
    }
    return last_nonspace_end;
}

/* Codepoint count of rstripped string */
static int cp_rstrip_count(const char *s, char hb) {
    int end = cp_rstrip_bytes(s, hb);
    int n = 0;
    for (int i = 0; i < end; ) {
        unsigned char c = (unsigned char)s[i];
        int cplen = 1;
        if (c >= 0xF0) cplen = 4;
        else if (c >= 0xE0) cplen = 3;
        else if (c >= 0xC0) cplen = 2;
        n++;
        i += cplen;
    }
    return n;
}

'''

# Find flushBuf and add the functions before it
old_flush = 'static void flushBuf(LineBuf *buf, int justify, int rtl, int outw){'
if old_flush in content:
    content = content.replace(old_flush, cpfunc + old_flush)
    print("Added codepoint functions")
else:
    print("Could not find flushBuf!")

with open('figlet3.c', 'w') as f:
    f.write(content)
